/* NHPC Diploma in Operation Theatre Technology — syllabus mapped study module.
   Initial bilingual bank: 48 unique MCQs (24 practice + 24 mock); expand in reviewed batches.
   Based on NHPC Diploma in OTT Licensing Syllabus 2021. */
(()=>{const root=document.getElementById("ottContent");if(!root||root.dataset.ready==="1")return;root.dataset.ready="1";
const Q=[["Which anatomical plane divides the body into right and left parts?","शरीरलाई दायाँ र बायाँ भागमा छुट्याउने anatomical plane कुन हो?",["Coronal","Sagittal","Transverse","Oblique"],1,"The sagittal plane divides the body into right and left portions.","Sagittal plane ले शरीरलाई दायाँ र बायाँ भागमा विभाजन गर्छ।","Anatomy"],["Which organ is primarily responsible for gas exchange?","ग्यासको आदानप्रदान मुख्य रूपमा कुन अंगमा हुन्छ?",["Liver","Kidney","Lungs","Stomach"],2,"Gas exchange occurs across the alveolar-capillary membrane in the lungs.","फोक्सोका alveoli र capillaries बीच oxygen र carbon dioxide को आदानप्रदान हुन्छ।","Anatomy"],["What is the functional unit of the kidney?","मिर्गौलाको functional unit कुन हो?",["Neuron","Nephron","Alveolus","Hepatocyte"],1,"The nephron filters blood and forms urine.","Nephron ले रगत छानेर पिसाब बनाउन मद्दत गर्छ।","Anatomy"],["Which hormone lowers blood glucose?","रगतमा glucose घटाउने hormone कुन हो?",["Glucagon","Adrenaline","Insulin","Cortisol"],2,"Insulin promotes glucose uptake and storage, lowering blood glucose.","Insulin ले glucose को uptake र storage बढाएर blood glucose घटाउँछ।","Anatomy"],["The basic structural and functional unit of the nervous system is:","Nervous system को आधारभूत संरचनात्मक तथा कार्यात्मक एकाइ कुन हो?",["Neuron","Nephron","Osteon","Alveolus"],0,"A neuron receives and transmits nerve impulses.","Neuron ले nerve impulse ग्रहण र प्रसारण गर्छ।","Anatomy"],["Which electrolyte is the major extracellular cation?","कोषबाहिरको तरलमा मुख्य cation कुन हो?",["Potassium","Sodium","Magnesium","Phosphate"],1,"Sodium is the major extracellular cation and is important for fluid balance.","Sodium extracellular fluid को मुख्य cation हो र fluid balance मा महत्त्वपूर्ण छ।","Biochemistry"],["Which test is commonly used to assess renal filtration?","मिर्गौलाको filtration मूल्याङ्कन गर्न कुन परीक्षण प्रयोग गरिन्छ?",["Serum creatinine/eGFR","Serum amylase","Troponin only","Bilirubin only"],0,"Serum creatinine is used to estimate glomerular filtration rate (eGFR).","Serum creatinine बाट eGFR अनुमान गरी renal filtration मूल्याङ्कन गरिन्छ।","Biochemistry"],["The normal blood pH is approximately:","रगतको सामान्य pH लगभग कति हुन्छ?",["6.8–7.0","7.35–7.45","7.8–8.0","8.2–8.4"],1,"Normal arterial blood pH is maintained around 7.35–7.45.","सामान्य arterial blood pH 7.35–7.45 बीच कायम रहन्छ।","Biochemistry"],["Which route gives a drug directly into a vein?","औषधि सिधै नसामा दिने route कुन हो?",["Intramuscular","Subcutaneous","Intravenous","Intradermal"],2,"Intravenous administration delivers medication directly into the venous circulation.","Intravenous route बाट औषधि सिधै venous circulation मा पुग्छ।","Pharmacology"],["An antiseptic is primarily used on:","Antiseptic मुख्य रूपमा कहाँ प्रयोग गरिन्छ?",["Living tissue","Floors only","Metal instruments only","Waste bins"],0,"Antiseptics are chemical agents used on living tissue to reduce microorganisms.","Antiseptic जीवित tissue/छालामा microorganism घटाउन प्रयोग गरिन्छ।","Pharmacology"],["Which organism is commonly associated with surgical wound infection?","Surgical wound infection सँग सामान्यतया कुन जीवाणु सम्बन्धित हुन्छ?",["Staphylococcus aureus","Plasmodium vivax","Entamoeba histolytica","Rhinovirus"],0,"Staphylococcus aureus is a common cause of surgical site infection.","Staphylococcus aureus surgical site infection को सामान्य कारण हो।","Microbiology"],["What is the main purpose of hand hygiene before a sterile procedure?","Sterile procedure अघि hand hygiene गर्नुको मुख्य उद्देश्य के हो?",["Improve grip","Reduce transmission of microorganisms","Warm the hands","Remove glove powder only"],1,"Hand hygiene reduces microbial transmission and protects patients and staff.","Hand hygiene ले microorganism सर्ने जोखिम घटाएर बिरामी र स्वास्थ्यकर्मीलाई जोगाउँछ।","Microbiology"],["Which method is commonly used to sterilize heat-stable surgical instruments?","Heat-stable surgical instruments sterilize गर्न सामान्यतया कुन विधि प्रयोग गरिन्छ?",["Autoclaving","Wiping with water","Sun drying","Rinsing with saline"],0,"Validated steam sterilization in an autoclave is commonly used for heat- and moisture-stable instruments.","Heat र moisture सहने उपकरणमा validated autoclave steam sterilization प्रयोग गरिन्छ।","Microbiology"],["What does PPE stand for?","PPE को पूरा रूप के हो?",["Patient Protection Equipment","Personal Protective Equipment","Primary Prevention Element","Personal Procedure Evaluation"],1,"PPE means personal protective equipment, selected according to exposure risk.","PPE को अर्थ Personal Protective Equipment हो; exposure risk अनुसार छनोट गरिन्छ।","Microbiology"],["Who is a member of the sterile surgical team?","Sterile surgical team को सदस्य को हो?",["Scrub person","Receptionist","Ward clerk","Porter outside the room"],0,"The scrub person works within the sterile field and handles sterile instruments.","Scrub person sterile field भित्र काम गर्छ र sterile instruments सम्हाल्छ।","OT Technique"],["The main purpose of the circulating nurse/OT assistant is to:","Circulating nurse/OT assistant को मुख्य भूमिका के हो?",["Remain sterile at all times","Coordinate non-sterile activities and support the sterile team","Perform the operation independently","Prescribe antibiotics"],1,"The circulating team member coordinates room activities, documentation, supplies and patient safety outside the sterile field.","Circulating staff ले sterile field बाहिरका काम, documentation, सामान र patient safety समन्वय गर्छ।","OT Technique"],["A sterile field should be considered contaminated when:","कुन अवस्थामा sterile field दूषित भएको मानिन्छ?",["It is kept in view","A sterile item touches a non-sterile surface","A sterile drape is dry","The procedure is delayed briefly"],1,"Contact with a non-sterile surface compromises sterility and requires corrective action.","Non-sterile सतह छोएमा sterility बिग्रन्छ र आवश्यक corrective action लिनुपर्छ।","OT Technique"],["Which item is used to protect the patient and maintain a sterile operative field?","बिरामीलाई ढाकेर sterile operative field कायम गर्न कुन वस्तु प्रयोग हुन्छ?",["Surgical drape","Bed sheet from ward","Paper towel","Reusable blanket without processing"],0,"Sterile surgical drapes isolate the operative site and help maintain the sterile field.","Sterile surgical drape ले operation site छुट्याएर sterile field कायम गर्न मद्दत गर्छ।","OT Technique"],["What is the purpose of surgical hand antisepsis?","Surgical hand antisepsis को उद्देश्य के हो?",["Remove all skin cells","Reduce transient flora and suppress resident flora","Replace sterilization of instruments","Make gloves unnecessary"],1,"Surgical hand antisepsis reduces transient microorganisms and suppresses resident flora for the procedure.","यसले transient microorganism घटाउँछ र resident flora लाई दबाउँछ।","OT Technique"],["Which count is performed to prevent retained surgical items?","शल्यक्रियामा वस्तु शरीरभित्र छुट्न नदिन कुन count गरिन्छ?",["Sponge, sharp and instrument count","Patient meal count","Staff attendance count","Drug expiry count only"],0,"Counts of sponges, sharps and instruments are performed according to policy at defined stages.","Sponge, sharp र instrument count संस्थाको protocol अनुसार निश्चित चरणमा गरिन्छ।","OT Technique"],["What is the primary purpose of the WHO Surgical Safety Checklist?","WHO Surgical Safety Checklist को मुख्य उद्देश्य के हो?",["Increase operation speed only","Improve communication and reduce preventable harm","Replace consent","Avoid patient identification"],1,"The checklist supports team communication and checks key safety steps before, during and after surgery.","Checklist ले team communication र surgery का मुख्य safety steps जाँच्न मद्दत गर्छ।","OT Technique"],["Which gas is commonly used to insufflate the abdomen in laparoscopy?","Laparoscopy मा पेट फुलाउन सामान्यतया कुन gas प्रयोग गरिन्छ?",["Oxygen","Nitrogen","Carbon dioxide","Helium"],2,"Carbon dioxide is commonly used because it is non-flammable and readily absorbed.","Carbon dioxide non-flammable र शरीरले सजिलै absorb गर्ने भएकाले सामान्यतया प्रयोग हुन्छ।","OT Technique"],["A surgical specimen for histopathology should be:","Histopathology का लागि surgical specimen कसरी पठाउनुपर्छ?",["Left unlabelled","Correctly labelled and placed in the appropriate fixative as directed","Mixed with all other specimens","Discarded after removal"],1,"Correct identification, labelling and the laboratory-specified fixative preserve specimen integrity.","सही पहिचान, label र laboratory ले तोकेको fixative ले specimen सुरक्षित राख्छ।","OT Technique"],["Which device removes fluid and smoke from the operative field?","Operation field बाट fluid र smoke हटाउन कुन उपकरण प्रयोग हुन्छ?",["Suction system","Pulse oximeter","ECG electrode","Laryngoscope"],0,"Suction removes blood and fluids; dedicated smoke evacuation may be needed for surgical plume.","Suction ले रगत तथा fluid हटाउँछ; surgical plume का लागि छुट्टै smoke evacuation आवश्यक हुन सक्छ।","OT Technique"],["What is the safest immediate response to an electrical equipment fault during surgery?","Surgery चल्दा electrical equipment मा खराबी आएमा सुरक्षित तत्काल कदम के हो?",["Continue using it","Stop using it and alert the responsible team according to protocol","Touch exposed wires","Pour water on the device"],1,"Remove faulty equipment from use, maintain patient safety and report it according to local policy.","खराब उपकरण प्रयोग बन्द गरी बिरामी सुरक्षित राख्ने र protocol अनुसार जानकारी दिने।","OT Technique"],["Which monitoring device measures peripheral oxygen saturation?","Peripheral oxygen saturation मापन गर्ने उपकरण कुन हो?",["Pulse oximeter","Sphygmomanometer","Capnograph only","Thermometer"],0,"A pulse oximeter estimates oxygen saturation (SpO2) and pulse rate.","Pulse oximeter ले SpO2 र pulse rate अनुमान गर्छ।","Anaesthesia"],["Capnography primarily measures:","Capnography ले मुख्य रूपमा के मापन गर्छ?",["End-tidal carbon dioxide","Blood glucose","Haemoglobin","Urine output"],0,"Capnography monitors exhaled carbon dioxide, commonly displayed as end-tidal CO2 (EtCO2).","Capnography ले सास बाहिर निकाल्दा निस्कने CO2, सामान्यतया EtCO2, monitor गर्छ।","Anaesthesia"],["Which airway device is placed through the vocal cords into the trachea?","Vocal cords हुँदै trachea भित्र राखिने airway device कुन हो?",["Oropharyngeal airway","Endotracheal tube","Face mask","Nasal cannula"],1,"An endotracheal tube passes through the vocal cords into the trachea to secure the airway.","Endotracheal tube vocal cords पार गरी trachea मा राखेर airway सुरक्षित गर्छ।","Anaesthesia"],["The main purpose of pre-anaesthetic assessment is to:","Pre-anaesthetic assessment को मुख्य उद्देश्य के हो?",["Choose the patient's meal","Identify risks and plan safe anaesthesia","Guarantee no complications","Skip consent"],1,"Assessment identifies comorbidities, airway concerns, medications, allergies and risks to guide planning.","यसले रोग, airway, औषधि, allergy र जोखिम पहिचान गरी सुरक्षित योजना बनाउन मद्दत गर्छ।","Anaesthesia"],["Which drug class is commonly used for neuromuscular blockade?","Neuromuscular blockade का लागि कुन drug class प्रयोग हुन्छ?",["Neuromuscular blocking agents","Antacids","Antihistamines","Antifungals"],0,"Neuromuscular blocking agents produce temporary skeletal muscle paralysis and require appropriate airway and ventilation support.","यी औषधिले अस्थायी muscle paralysis गराउँछन्; airway र ventilation support आवश्यक हुन्छ।","Anaesthesia"],["Which position is commonly used for many abdominal operations?","धेरै abdominal operation मा सामान्यतया कुन position प्रयोग हुन्छ?",["Supine","Lithotomy in every case","Prone in every case","Sitting in every case"],0,"Supine is common for many abdominal procedures, but positioning must be tailored to the operation and patient.","धेरै abdominal surgery मा supine प्रयोग हुन्छ, तर procedure र बिरामीअनुसार position मिलाउनुपर्छ।","Patient Positioning"],["A major risk of prolonged lithotomy position is:","लामो समय lithotomy position राख्दा हुने प्रमुख जोखिम के हो?",["Peripheral nerve injury","Improved circulation in all patients","Reduced pressure injury risk","No risk"],0,"Prolonged or poorly supported lithotomy positioning can cause nerve compression and compartment-related injury.","लामो समय वा गलत support ले nerve compression र compartment सम्बन्धी चोट हुन सक्छ।","Patient Positioning"],["Which position is commonly used for posterior spinal surgery?","Posterior spinal surgery मा सामान्यतया कुन position प्रयोग हुन्छ?",["Prone","Supine","Lithotomy","Trendelenburg"],0,"Prone positioning provides access to the posterior spine; pressure points, eyes and airway require careful protection.","Prone position ले पछाडिको मेरुदण्डमा पहुँच दिन्छ; pressure points, आँखा र airway जोगाउनुपर्छ।","Patient Positioning"],["What is the first priority when receiving a patient in the operating room?","Operating room मा बिरामी प्राप्त गर्दा पहिलो प्राथमिकता के हो?",["Confirm identity using approved identifiers","Ask about payment","Start incision preparation immediately","Remove all jewellery without explanation"],0,"Correct patient identification and matching the procedure and consent are essential safety checks.","सही बिरामी, procedure र consent मिलाउनु आधारभूत safety check हो।","Preoperative Care"],["Which document confirms that the patient has been informed and agrees to the procedure?","बिरामीलाई जानकारी दिइएको र procedure गर्न सहमति भएको पुष्टि गर्ने कागजात कुन हो?",["Informed consent","Discharge summary","Instrument list","Diet chart"],0,"Informed consent documents a voluntary decision after adequate explanation by the responsible clinician.","जिम्मेवार clinician ले पर्याप्त जानकारी दिएपछि बिरामीले स्वेच्छाले दिएको सहमति document गरिन्छ।","Preoperative Care"],["Which action helps prevent wrong-site surgery?","गलत स्थानमा surgery हुन नदिन कुन कदमले मद्दत गर्छ?",["Site marking and team verification","Relying on memory","Skipping the time-out","Preparing two patients together"],0,"Site marking, identity/procedure verification and a team time-out reduce wrong-site risk.","Site marking, बिरामी/प्रक्रिया verification र team time-out ले गलत site को जोखिम घटाउँछ।","Preoperative Care"],["What is the purpose of surgical skin preparation?","Surgical skin preparation को उद्देश्य के हो?",["Reduce microorganisms at the operative site","Sterilize deep organs","Replace hand hygiene","Remove the need for antibiotics in all cases"],0,"Appropriate antiseptic skin preparation reduces microbial load at the incision site.","उपयुक्त antiseptic ले incision site मा microorganism को मात्रा घटाउँछ।","Surgery"],["Which phase of wound healing is characterized by collagen deposition and granulation tissue formation?","Collagen जम्ने र granulation tissue बन्ने wound healing चरण कुन हो?",["Proliferative phase","Haemostasis only","Maturation only","Immediate contamination"],0,"The proliferative phase includes fibroblast activity, collagen deposition, angiogenesis and granulation tissue formation.","Proliferative phase मा fibroblast, collagen, नयाँ रक्तनली र granulation tissue बन्छ।","Surgery"],["Which instrument is commonly used to grasp tissue atraumatically?","Tissue लाई कम चोट पुर्‍याएर समात्न कुन instrument प्रयोग हुन्छ?",["Appropriate atraumatic forceps","Bone saw","Suction catheter","Retractor only"],0,"Atraumatic forceps are selected to hold delicate tissue while minimizing crush injury.","Delicate tissue कम चोट पुर्‍याएर समात्न atraumatic forceps छानिन्छ।","Surgical Instruments"],["Which suture is generally absorbed by the body over time?","शरीरले समयसँगै absorb गर्ने suture कुन हो?",["Absorbable suture","Permanent non-absorbable suture","Stainless steel wire only","Silk in every case"],0,"Absorbable sutures degrade through hydrolysis or enzymatic processes; selection depends on tissue and procedure.","Absorbable suture hydrolysis वा enzymatic प्रक्रियाबाट घट्छ; छनोट tissue र procedure अनुसार हुन्छ।","Surgical Materials"],["What is the purpose of a surgical drain?","Surgical drain को उद्देश्य के हो?",["Allow collection or removal of fluid/air from a surgical site","Sterilize the wound","Replace haemostasis","Measure blood glucose"],0,"Drains may remove or monitor fluid or air when clinically indicated; they are not required in every operation.","आवश्यक अवस्थामा drain ले surgical site बाट fluid वा air निकाल्न/monitor गर्न मद्दत गर्छ।","Surgery"],["Which procedure uses an endoscope to visualize the abdominal cavity through small ports?","सानो port बाट endoscope प्रयोग गरी पेटभित्र हेर्ने procedure कुन हो?",["Laparoscopy","Thoracotomy","Craniotomy","Arthrodesis"],0,"Laparoscopy uses a camera and instruments introduced through small abdominal ports.","Laparoscopy मा पेटका साना port बाट camera र instruments प्रवेश गराइन्छ।","Operative Procedures"],["Which operation removes the gallbladder?","Gallbladder हटाउने operation कुन हो?",["Cholecystectomy","Appendectomy","Nephrectomy","Colectomy"],0,"Cholecystectomy is surgical removal of the gallbladder.","Cholecystectomy भनेको gallbladder हटाउने शल्यक्रिया हो।","Operative Procedures"],["Which operation removes the appendix?","Appendix हटाउने operation कुन हो?",["Appendectomy","Gastrectomy","Hysterectomy","Mastectomy"],0,"Appendectomy is removal of the appendix, commonly for appendicitis.","Appendectomy मा appendix हटाइन्छ, प्रायः appendicitis का लागि।","Operative Procedures"],["Which specialty commonly performs cataract extraction?","Cataract extraction कुन specialty अन्तर्गत पर्छ?",["Ophthalmology","Urology","Orthopaedics","Neurosurgery"],0,"Cataract surgery is an ophthalmic procedure involving removal of the cloudy lens and usually intraocular lens implantation.","Cataract surgery आँखाको lens हटाएर प्रायः intraocular lens राख्ने ophthalmic procedure हो।","Operative Procedures"],["Which procedure is used to repair a hernia?","Hernia मर्मत गर्ने procedure कुन हो?",["Herniorrhaphy/hernia repair","Cholecystectomy","Cystoscopy","Myringotomy"],0,"Hernia repair returns or reinforces tissue at the defect, with technique selected by the surgeon.","Hernia repair मा defect भएको भाग मर्मत वा reinforce गरिन्छ।","Operative Procedures"],["What is the key purpose of haemostasis during surgery?","Surgery गर्दा haemostasis को मुख्य उद्देश्य के हो?",["Control bleeding","Increase blood loss","Delay wound healing","Sterilize instruments"],0,"Haemostasis controls bleeding and supports safe visualization and patient stability.","Haemostasis ले रक्तस्राव नियन्त्रण गरी सुरक्षित operation र बिरामीको स्थिरता कायम गर्न मद्दत गर्छ।","Surgery"],["Which complication may occur after surgery due to reduced ventilation and immobility?","शल्यक्रियापछि ventilation कम र चलायमानता घट्दा कुन complication हुन सक्छ?",["Atelectasis","Improved lung expansion","Hyperthyroidism","Cataract"],0,"Atelectasis is collapse of alveoli and can occur after surgery, especially with shallow breathing and immobility.","Atelectasis भनेको alveoli खुम्चिनु हो; shallow breathing र immobility पछि हुन सक्छ।","Postoperative Care"],["A patient develops sudden severe bleeding during surgery. The OT team should first:","Surgery चल्दा अचानक धेरै रक्तस्राव भएमा OT team ले पहिले के गर्नुपर्छ?",["Alert the surgeon/anesthesia team and follow emergency haemorrhage protocol","Leave the room","Continue routine cleaning","Remove monitoring"],0,"Immediate team communication, support of circulation and the local haemorrhage protocol are essential.","तुरुन्त team लाई जानकारी, circulation support र संस्थाको haemorrhage protocol पालना आवश्यक हुन्छ।","Emergency Care"],["Which forceps is designed to grasp delicate tubular structures with minimal crushing?","नाजुक tubular structure कम क्षति गरी समात्न कुन forceps बनाइएको हो?",["Allis","Babcock","Kocher","Towel clip"],1,"Babcock forceps is relatively atraumatic and is used for delicate tubular structures.","Babcock forceps तुलनात्मक रूपमा atraumatic हुन्छ र नाजुक tubular structure समात्न प्रयोग हुन्छ।","Instruments"],["Which scissors are preferred for delicate tissue dissection?","नाजुक tissue dissect गर्न कुन scissors उपयुक्त हुन्छ?",["Mayo","Metzenbaum","Wire cutter","Bone scissors"],1,"Metzenbaum scissors are designed for delicate tissue dissection.","Metzenbaum scissors नाजुक tissue dissect गर्न बनाइएको हो।","Instruments"],["Which instrument secures surgical drapes?","Surgical drape अड्याउन कुन instrument प्रयोग हुन्छ?",["Towel clip","Needle holder","Suction cannula","Retractor"],0,"Towel clips secure drapes; use carefully to avoid injury.","Towel clip ले drape अड्याउँछ; चोट नपुग्ने गरी प्रयोग गर्नुपर्छ।","Instruments"],["Which instrument removes blood and fluid from the operative field?","Operation field बाट रगत र तरल हटाउन कुन उपकरण प्रयोग हुन्छ?",["Suction cannula","Osteotome","Tenaculum","Retractor"],0,"Suction cannula removes fluid and improves visibility.","Suction cannula ले तरल हटाएर operation site स्पष्ट बनाउँछ।","Instruments"],["Which instrument is used to cut or shape bone?","हड्डी काट्न वा आकार दिन कुन instrument प्रयोग हुन्छ?",["Osteotome","Artery forceps","Needle holder","Sponge forceps"],0,"An osteotome is a chisel-like instrument used on bone.","Osteotome छिनीजस्तो instrument हो, हड्डीमा प्रयोग हुन्छ।","Instruments"],["Which instrument holds a suture needle during suturing?","Suturing गर्दा सुई समात्ने instrument कुन हो?",["Needle holder","Towel clip","Sponge forceps","Retractor"],0,"A needle holder securely grips the suture needle.","Needle holder ले सिउने सुई सुरक्षित रूपमा समात्छ।","Instruments"],["Which statement best describes balanced anaesthesia?","Balanced anaesthesia भन्नाले के बुझिन्छ?",["Use of several agents/techniques to achieve desired components of anaesthesia","Use of only one drug in every patient","Keeping the patient awake throughout surgery","Avoiding monitoring"],0,"Balanced anaesthesia combines suitable agents or techniques to provide hypnosis, analgesia and immobility while limiting adverse effects.","Balanced anaesthesia मा उपयुक्त औषधि/विधि मिलाएर hypnosis, analgesia र immobility प्राप्त गरिन्छ र side effect कम गर्ने प्रयास गरिन्छ।","Anaesthesia"],["Which is a common purpose of premedication before anaesthesia?","Anaesthesia अघि premedication दिनुको सामान्य उद्देश्य के हो?",["Reduce anxiety and provide selected effects such as analgesia or secretion reduction","Replace airway assessment","Guarantee absence of aspiration","Replace informed consent"],0,"Premedication is selected for the individual patient and may reduce anxiety, pain or secretions as clinically indicated.","बिरामीको अवस्था अनुसार premedication ले anxiety, pain वा secretion घटाउन मद्दत गर्न सक्छ।","Anaesthesia"],["Spinal anaesthesia is administered into the:","Spinal anaesthesia कहाँ दिइन्छ?",["Subarachnoid space containing CSF","Pleural cavity","Peritoneal cavity","Epidural space only"],0,"Spinal anaesthesia is injected into the subarachnoid space, where it mixes with cerebrospinal fluid.","Spinal anaesthesia subarachnoid space मा CSF सँग मिसिने गरी दिइन्छ।","Anaesthesia"],["Epidural anaesthesia is administered into the:","Epidural anaesthesia कहाँ दिइन्छ?",["Epidural space outside the dura","Subarachnoid space","Ventricular system","Pleural space"],0,"An epidural injection is placed in the epidural space outside the dura mater.","Epidural injection dura mater बाहिरको epidural space मा दिइन्छ।","Anaesthesia"],["Which local anaesthetic toxicity sign may occur early in the central nervous system?","Local anaesthetic systemic toxicity मा CNS को प्रारम्भिक संकेत कुन हुन सक्छ?",["Circumoral numbness, tinnitus or metallic taste","Hair loss","Jaundice","Polyuria"],0,"Early neurological symptoms can include circumoral numbness, tinnitus, metallic taste, agitation or seizures; urgent protocol-based care is required.","मुख वरिपरि numbness, कानमा आवाज, metallic taste, बेचैनी वा seizure देखिन सक्छ; तुरुन्त protocol अनुसार उपचार चाहिन्छ।","Anaesthesia"],["Which monitor is essential for continuous assessment of oxygenation during general anaesthesia?","General anaesthesia मा oxygenation निरन्तर हेर्न कुन monitor महत्त्वपूर्ण हुन्छ?",["Pulse oximeter","Urine dipstick","Glucometer only","Peak flow meter only"],0,"Pulse oximetry provides continuous SpO2 monitoring and should be interpreted with the full clinical picture.","Pulse oximeter ले SpO2 निरन्तर देखाउँछ; अन्य clinical जानकारीसँग मिलाएर बुझ्नुपर्छ।","Anaesthesia"],["A sudden rise in end-tidal CO2 with rigidity and hyperthermia during anaesthesia may suggest:","Anaesthesia का बेला EtCO2 अचानक बढ्नु, शरीर कडा हुनु र ज्वरो आउनु कुन अवस्थाको संकेत हुन सक्छ?",["Malignant hyperthermia","Hypoglycaemia only","Simple motion sickness","Cataract"],0,"Malignant hyperthermia is a life-threatening anaesthetic emergency; activate the emergency protocol and use specific treatment such as dantrolene per protocol.","Malignant hyperthermia जीवन जोखिमपूर्ण emergency हो; तुरुन्त emergency protocol र dantrolene सहितको उपचार आवश्यक पर्न सक्छ।","Anaesthesia Complications"],["Which drug is a commonly used neuromuscular blocking agent?","Neuromuscular blocking agent को उदाहरण कुन हो?",["Rocuronium","Paracetamol","Amoxicillin","Omeprazole"],0,"Rocuronium is a non-depolarizing neuromuscular blocker used by trained anaesthesia professionals with airway and ventilation support.","Rocuronium non-depolarizing muscle relaxant हो; airway र ventilation support सहित प्रशिक्षित टोलीले प्रयोग गर्छ।","Anaesthesia Drugs"],["Which drug is a reversal agent for benzodiazepine sedation in selected situations?","केही अवस्थामा benzodiazepine को प्रभाव उल्ट्याउन कुन औषधि प्रयोग हुन्छ?",["Flumazenil","Naloxone","Atropine","Adrenaline"],0,"Flumazenil antagonizes benzodiazepines; use requires careful assessment because resedation and seizures may occur in some patients.","Flumazenil ले benzodiazepine को प्रभाव रोक्छ; केही बिरामीमा पुनः sedation वा seizure जोखिम भएकाले सावधानी चाहिन्छ।","Anaesthesia Drugs"],["Which medicine reverses opioid-induced respiratory depression?","Opioid का कारण भएको respiratory depression उल्ट्याउन कुन औषधि प्रयोग हुन्छ?",["Naloxone","Flumazenil","Neostigmine","Lidocaine"],0,"Naloxone is an opioid antagonist used to reverse opioid toxicity, with repeat dosing and monitoring sometimes required.","Naloxone opioid antagonist हो; आवश्यक परे दोहोर्‍याएर दिन र बिरामी monitor गर्नुपर्छ।","Anaesthesia Drugs"],["Which drug class is used to treat bronchospasm?","Bronchospasm उपचार गर्न कुन drug class प्रयोग हुन्छ?",["Bronchodilators","Anticoagulants","Antifungals","Antacids"],0,"Bronchodilators such as inhaled beta-2 agonists can relieve bronchospasm according to clinical protocol.","Inhaled beta-2 agonist जस्ता bronchodilator ले protocol अनुसार bronchospasm घटाउन सक्छ।","Anaesthesia Drugs"],["Which drug class may be used to increase vascular tone in severe hypotension?","गम्भीर hypotension मा vascular tone बढाउन कुन औषधि वर्ग प्रयोग हुन सक्छ?",["Vasopressors","Antacids","Antihistamines","Antifungals"],0,"Vasopressors support blood pressure in selected shock states and require close monitoring.","केही shock अवस्थामा vasopressor ले blood pressure support गर्छ; नजिकबाट monitor गर्नुपर्छ।","Anaesthesia Drugs"],["Which drug is commonly used for induction of general anaesthesia?","General anaesthesia सुरु गर्न commonly प्रयोग हुने औषधि कुन हो?",["Propofol","Atropine","Furosemide","Amoxicillin"],0,"Propofol is a commonly used intravenous induction agent; choice depends on the patient's condition and clinical judgement.","Propofol सामान्य intravenous induction agent हो; छनोट बिरामीको अवस्था र clinical judgement अनुसार हुन्छ।","Anaesthesia Pharmacology"],["Which medicine is a depolarizing neuromuscular blocking agent?","Depolarizing neuromuscular blocking agent कुन हो?",["Vecuronium","Atracurium","Succinylcholine","Neostigmine"],2,"Succinylcholine is a depolarizing neuromuscular blocker used in selected situations for rapid paralysis.","Succinylcholine depolarizing neuromuscular blocker हो, केही अवस्थामा छिटो paralysis का लागि प्रयोग हुन्छ।","Anaesthesia Pharmacology"],["Which drug reverses opioid-induced respiratory depression?","Opioid का कारण भएको respiratory depression उल्ट्याउन कुन औषधि प्रयोग गरिन्छ?",["Naloxone","Flumazenil","Neostigmine","Adrenaline"],0,"Naloxone is an opioid antagonist used to reverse opioid toxicity, while airway and ventilation support remain essential.","Naloxone opioid antagonist हो; opioid toxicity मा प्रयोग हुन्छ, साथै airway र ventilation support अत्यावश्यक हुन्छ।","Anaesthesia Pharmacology"],["Which parameter is most directly monitored by pulse oximetry?","Pulse oximetry ले प्रत्यक्ष रूपमा कुन parameter मापन गर्छ?",["Blood glucose","Peripheral oxygen saturation","Urine output","Core temperature"],1,"Pulse oximetry estimates peripheral arterial oxygen saturation (SpO₂); it does not directly measure ventilation or carbon dioxide.","Pulse oximetry ले peripheral oxygen saturation (SpO₂) अनुमान गर्छ; ventilation वा carbon dioxide प्रत्यक्ष मापन गर्दैन।","Anaesthesia Monitoring"],["Which monitor helps assess ventilation by measuring exhaled carbon dioxide?","निस्किएको carbon dioxide मापन गरेर ventilation मूल्याङ्कन गर्ने monitor कुन हो?",["ECG","Capnograph","Pulse oximeter","Non-invasive BP cuff"],1,"Capnography measures exhaled CO₂ and provides information about ventilation and airway/circulatory changes.","Capnography ले exhaled CO₂ मापन गरी ventilation तथा airway/circulation परिवर्तनबारे जानकारी दिन्छ।","Anaesthesia Monitoring"],["What is the first priority when a patient is found unresponsive and not breathing normally?","बिरामी अचेत र सामान्य रूपमा सास नफेरेको भेटिएमा पहिलो प्राथमिकता के हो?",["Give oral fluids","Activate emergency response and start CPR as indicated","Wait for spontaneous recovery","Move the patient to another room"],1,"Call for help/activate the emergency response, assess breathing and pulse according to training, and begin CPR promptly when indicated.","सहयोग बोलाउने/emergency response सक्रिय गर्ने, तालिमअनुसार सास र pulse जाँच्ने र आवश्यक भए तुरुन्त CPR सुरु गर्ने।","CPR"],["For an adult with cardiac arrest, the recommended chest compression rate is:","Adult cardiac arrest मा chest compression को सिफारिस गरिएको गति कति हो?",["40–60 per minute","60–80 per minute","100–120 per minute","140–160 per minute"],2,"Adult CPR uses a compression rate of 100–120 per minute with adequate depth and full recoil, following current resuscitation guidance.","Adult CPR मा हालको resuscitation guideline अनुसार प्रति मिनेट 100–120 compression, उचित गहिराइ र पूर्ण recoil आवश्यक हुन्छ।","CPR"],["Which blood group is considered the universal red-cell donor in emergency teaching?","Emergency teaching मा universal red-cell donor कुन blood group लाई मानिन्छ?",["AB positive","O negative","A positive","B negative"],1,"O negative red cells lack A, B and Rh(D) antigens and may be used in emergencies under transfusion policy; compatibility testing remains important.","O negative red cells मा A, B र Rh(D) antigen हुँदैन; emergency मा policy अनुसार प्रयोग हुन सक्छ, तर compatibility testing महत्त्वपूर्ण रहन्छ।","Blood Transfusion"],["What should be done first if an acute transfusion reaction is suspected?","Acute transfusion reaction शंका भएमा सबैभन्दा पहिले के गर्नुपर्छ?",["Increase the transfusion rate","Stop the transfusion immediately","Discard the blood bag without reporting","Give the next unit"],1,"Stop the transfusion, maintain IV access with compatible normal saline using new tubing as per protocol, assess the patient and notify the responsible clinician/blood bank.","Transfusion तुरुन्त रोक्ने, protocol अनुसार नयाँ tubing बाट normal saline ले IV access कायम गर्ने, बिरामी मूल्याङ्कन गर्ने र जिम्मेवार clinician/blood bank लाई खबर गर्ने।","Blood Transfusion"],["Which test checks compatibility between donor red cells and recipient serum?","Donor red cells र recipient serum बीच compatibility जाँच्ने test कुन हो?",["Crossmatch","Bleeding time","ESR","Urine culture"],0,"Crossmatching detects clinically significant incompatibility before transfusion.","Crossmatch ले transfusion अघि clinically significant incompatibility पत्ता लगाउन मद्दत गर्छ।","Blood Transfusion"],["Which intravenous fluid is classified as an isotonic crystalloid?","कुन intravenous fluid isotonic crystalloid हो?",["0.9% sodium chloride","20% mannitol","Albumin 20%","Dextran 40"],0,"0.9% sodium chloride is an isotonic crystalloid commonly used when clinically indicated.","0.9% sodium chloride isotonic crystalloid हो र clinical indication अनुसार प्रयोग गरिन्छ।","Fluids"],["What is the purpose of a surgical time-out immediately before incision?","Incision अघि गरिने surgical time-out को उद्देश्य के हो?",["Check staff lunch schedule","Confirm correct patient, procedure and site with the team","Replace the consent process","Record instrument prices"],1,"A team time-out confirms patient identity, procedure, site/side and key safety concerns before starting.","Team time-out ले सुरु गर्नुअघि बिरामीको पहिचान, procedure, site/side र मुख्य safety concern पुष्टि गर्छ।","OT Practical Safety"],["What is the main function of surfactant in the lungs?","फोक्सोमा surfactant को मुख्य काम के हो?",["Reduce alveolar surface tension","Increase airway resistance","Thicken pleura","Stop pulmonary blood flow"],0,"Surfactant reduces surface tension and helps prevent alveolar collapse.","Surfactant ले surface tension घटाएर alveoli खुम्चिनबाट जोगाउँछ।","Physiology"],["Which structure carries urine from kidney to bladder?","मिर्गौलाबाट bladder सम्म पिसाब लैजाने संरचना कुन हो?",["Ureter","Urethra","Renal artery","Vas deferens"],0,"The ureter transports urine from the renal pelvis to the bladder.","Ureter ले renal pelvis बाट bladder सम्म पिसाब लैजान्छ।","Anatomy"],["Which hormone increases blood glucose during fasting?","उपवासमा blood glucose बढाउन कुन hormone ले मद्दत गर्छ?",["Glucagon","Insulin","Calcitonin","Oxytocin"],0,"Glucagon stimulates hepatic glycogen breakdown and glucose production.","Glucagon ले liver मा glycogen breakdown र glucose उत्पादन बढाउँछ।","Biochemistry"],["Which blood test is commonly used to assess anaemia?","Anaemia मूल्याङ्कन गर्न कुन blood test सामान्यतया प्रयोग हुन्छ?",["Haemoglobin level","Serum amylase","Troponin","Bilirubin only"],0,"Haemoglobin concentration helps assess the presence and severity of anaemia.","Haemoglobin ले anaemia को उपस्थिति र गम्भीरता मूल्याङ्कन गर्न मद्दत गर्छ।","Biochemistry"],["Which organism commonly causes tetanus?","Tetanus गराउने जीवाणु कुन हो?",["Clostridium tetani","Streptococcus pneumoniae","E. coli","Candida albicans"],0,"Clostridium tetani produces a neurotoxin that causes muscle rigidity and spasms.","Clostridium tetani को neurotoxin ले मांसपेशी कडा हुने र ऐंठन गराउँछ।","Microbiology"],["Which item is classified as critical in Spaulding classification?","Spaulding classification अनुसार critical item कुन हो?",["Surgical instrument entering sterile tissue","Blood pressure cuff","Stethoscope","Bedside table"],0,"Critical items enter sterile tissue or the vascular system and require sterilization.","Sterile tissue वा vascular system भित्र जाने critical item sterilize गर्नुपर्छ।","CSSD"],["What is the purpose of an internal chemical indicator in a pack?","Pack भित्रको chemical indicator को उद्देश्य के हो?",["Show that sterilant reached the pack interior","Prove sterility absolutely","Replace biological monitoring","Identify the patient"],0,"An internal chemical indicator helps show exposure conditions inside the package; it does not alone prove sterility.","Internal indicator ले pack भित्र sterilant पुगेको संकेत दिन्छ; यसले मात्र sterility प्रमाणित गर्दैन।","CSSD"],["Which action is correct if a sterile item touches a nonsterile surface?","Sterile सामान nonsterile सतहमा छोएमा के गर्नुपर्छ?",["Consider it contaminated","Wipe and continue","Assume it remains sterile","Use it if dry"],0,"Contact with a nonsterile surface contaminates the sterile item.","Nonsterile सतहमा छोएपछि sterile सामान contaminated मानिन्छ।","Asepsis"],["What is the purpose of the surgical time-out?","Surgical time-out को उद्देश्य के हो?",["Confirm patient, procedure and site before incision","Count recovery beds","Select postoperative diet","Replace consent"],0,"The team pauses before incision to verify patient identity, procedure and site.","Incision अघि team ले बिरामी, procedure र site पुष्टि गर्छ।","Patient Safety"],["Which position is commonly used for posterior spinal surgery?","Posterior spinal surgery मा कुन position सामान्य हुन्छ?",["Prone","Supine","Lithotomy","Trendelenburg"],0,"Prone positioning provides posterior access; pressure points and airway must be protected.","Prone position ले पछाडिको access दिन्छ; pressure point र airway सुरक्षित राख्नुपर्छ।","Positioning"],["Which instrument is used to hold back tissue for exposure?","Tissue हटाएर surgical field देखाउन कुन instrument प्रयोग हुन्छ?",["Retractor","Needle holder","Scalpel handle","Suction tubing"],0,"Retractors maintain exposure by holding tissue or wound edges aside.","Retractor ले tissue वा wound edge हटाएर field खुला राख्छ।","Instruments"],["Which monitor measures peripheral oxygen saturation?","Peripheral oxygen saturation मापन गर्ने monitor कुन हो?",["Pulse oximeter","Capnograph","ECG","NIBP cuff"],0,"Pulse oximetry estimates arterial oxygen saturation non-invasively.","Pulse oximeter ले non-invasive तरिकाले oxygen saturation अनुमान गर्छ।","Anaesthesia"],["What does a low end-tidal CO2 value during CPR often indicate?","CPR गर्दा end-tidal CO2 कम हुनुको अर्थ के हुन सक्छ?",["Low pulmonary blood flow or poor compression effectiveness","Excellent circulation always","High haemoglobin","Normal temperature"],0,"ETCO2 during CPR can reflect pulmonary blood flow and compression quality; interpret with the full clinical picture.","CPR मा ETCO2 ले pulmonary blood flow र compression quality को संकेत दिन सक्छ।","CPR"],["Which drug is a commonly used induction agent with dissociative properties?","Dissociative गुण भएको induction agent कुन हो?",["Ketamine","Midazolam only","Atracurium","Neostigmine"],0,"Ketamine produces dissociative anaesthesia and may preserve sympathetic tone.","Ketamine ले dissociative anaesthesia दिन्छ र sympathetic tone कायम राख्न सक्छ।","Pharmacology"],["Which drug is a depolarizing neuromuscular blocker?","Depolarizing neuromuscular blocker कुन हो?",["Succinylcholine","Rocuronium","Vecuronium","Cisatracurium"],0,"Succinylcholine is a depolarizing neuromuscular blocking agent.","Succinylcholine depolarizing neuromuscular blocker हो।","Pharmacology"],["Which clinical sign may indicate opioid overdose?","Opioid overdose को संकेत कुन हुन सक्छ?",["Respiratory depression with reduced consciousness","Wide awake with fast breathing","High fever alone","Rash on one finger"],0,"Opioid toxicity commonly causes reduced consciousness and respiratory depression; pinpoint pupils may occur.","Opioid toxicity मा चेतना घट्ने र श्वासप्रश्वास दबिने हुन सक्छ; pupil सानो हुन सक्छ।","Pharmacology"],["Which action helps prevent aspiration during induction in a high-risk patient?","उच्च जोखिम भएको बिरामीमा induction बेला aspiration रोक्न के मद्दत गर्छ?",["Follow aspiration-risk plan including appropriate positioning and airway strategy","Give oral water immediately","Ignore fasting history","Delay suction preparation"],0,"Aspiration prevention requires risk assessment and an appropriate anaesthetic/airway plan.","Aspiration रोक्न जोखिम मूल्याङ्कन र उपयुक्त anaesthesia/airway plan चाहिन्छ।","Anaesthesia"],["What is the first priority when a patient develops laryngospasm?","बिरामीमा laryngospasm भए पहिलो प्राथमिकता के हो?",["Call for help and support oxygenation/airway per protocol","Offer oral fluids","Remove all monitors","Wait without intervention"],0,"Laryngospasm can rapidly obstruct ventilation and requires immediate skilled airway management.","Laryngospasm ले ventilation रोक्न सक्छ; तुरुन्त दक्ष airway management चाहिन्छ।","Emergency"],["Which sign is commonly associated with bronchospasm under anaesthesia?","Anaesthesia मा bronchospasm को संकेत कुन हो?",["Wheezing with increased airway pressure","Very low airway resistance","Clear effortless ventilation always","Bradycardia alone"],0,"Bronchospasm can cause wheeze, prolonged expiration and increased airway pressures.","Bronchospasm मा wheeze, लामो expiration र airway pressure बढ्न सक्छ।","Emergency"],["What is the purpose of a blood crossmatch?","Blood crossmatch को उद्देश्य के हो?",["Check compatibility between donor red cells and recipient plasma","Measure blood glucose","Determine kidney size","Test sterilizer temperature"],0,"Crossmatching checks serological compatibility before transfusion.","Crossmatch ले transfusion अघि donor र recipient बीच serological compatibility जाँच्छ।","Transfusion"],["Which blood component is mainly used to improve oxygen-carrying capacity in significant anaemia?","गम्भीर anaemia मा oxygen बोक्ने क्षमता बढाउन कुन component दिइन्छ?",["Packed red blood cells","Platelets","Fresh frozen plasma","Cryoprecipitate"],0,"Packed red cells increase haemoglobin and oxygen-carrying capacity when indicated.","आवश्यक अवस्थामा packed red cells ले haemoglobin र oxygen बोक्ने क्षमता बढाउँछ।","Transfusion"],["Which sign may suggest an acute febrile non-haemolytic transfusion reaction?","Acute febrile non-haemolytic transfusion reaction को संकेत कुन हो?",["Fever and chills during or shortly after transfusion","Isolated ankle swelling","Hair loss","Improved vision"],0,"Fever and chills can occur, but serious haemolysis or sepsis must first be excluded.","ज्वरो र काम्ने हुन सक्छ; तर पहिले haemolysis वा sepsis जस्ता गम्भीर कारण हटाउनुपर्छ।","Transfusion"],["What is the purpose of a chest drain after thoracic surgery?","Thoracic surgery पछि chest drain को उद्देश्य के हो?",["Remove air, blood or fluid from pleural space","Deliver enteral feeding","Measure blood glucose","Drain urine"],0,"A chest drain helps evacuate air or fluid and supports lung re-expansion.","Chest drain ले pleural space बाट हावा वा तरल निकालेर फोक्सो फैलिन मद्दत गर्छ।","Thoracic Surgery"],["Which instrument is commonly used to grasp the cervix during selected gynaecological procedures?","केही gynaecological procedure मा cervix समात्न कुन instrument प्रयोग हुन्छ?",["Vulsellum forceps","Bone rongeur","Mayo scissors","Towel clip"],0,"Vulsellum forceps may be used to grasp the cervix when indicated.","आवश्यक अवस्थामा vulsellum forceps ले cervix समातिन्छ।","Gynaecology"],["Which practice is essential when using a tourniquet?","Tourniquet प्रयोग गर्दा कुन अभ्यास आवश्यक छ?",["Record inflation time and pressure and follow safety limits","Inflate without checking","Hide it under drapes without recording","Use it on every patient"],0,"Tourniquet pressure and duration must be monitored and documented to reduce injury risk.","चोटको जोखिम घटाउन tourniquet pressure र समय monitor तथा document गर्नुपर्छ।","Orthopaedics"],["Which device is commonly used to deliver a controlled concentration of inhaled anaesthetic gases?","सासबाट दिइने anaesthetic gas को निश्चित concentration दिन सामान्यतया कुन उपकरण प्रयोग हुन्छ?",["Suction regulator","Vapourizer","Pulse oximeter","Laryngoscope"],1,"A calibrated vapourizer adds a controlled concentration of volatile anaesthetic agent to fresh gas flow.","Calibrated vapourizer ले fresh gas flow मा volatile anaesthetic को नियन्त्रित मात्रा मिसाउँछ।","Anaesthesia"],["What is the primary purpose of pre-oxygenation before induction of general anaesthesia?","General anaesthesia induction अघि pre-oxygenation गर्नुको मुख्य उद्देश्य के हो?",["To prevent nausea","To increase oxygen reserve","To reduce blood pressure","To induce muscle relaxation"],1,"Pre-oxygenation replaces nitrogen in the lungs with oxygen and increases the safe apnoea time.","Pre-oxygenation ले फोक्सोमा nitrogen को ठाउँमा oxygen बढाएर केही समय सास नआए पनि सुरक्षित रहने अवधि बढाउँछ।","Anaesthesia"],["Which structure is directly visualized during conventional direct laryngoscopy?","सामान्य direct laryngoscopy गर्दा कुन संरचना प्रत्यक्ष देखिन्छ?",["Vocal cords","Oesophagus","Carina","Pleura"],0,"Direct laryngoscopy is used to visualize the glottis and vocal cords for tracheal intubation.","Tracheal intubation गर्दा glottis र vocal cords हेर्न direct laryngoscopy गरिन्छ।","Airway Management"],["Which monitoring parameter gives an early indication of ventilation adequacy during general anaesthesia?","General anaesthesia मा ventilation पर्याप्त छ कि छैन भन्ने प्रारम्भिक जानकारी कुन monitoring ले दिन्छ?",["Capnography","Temperature only","Urine colour","ECG limb lead only"],0,"End-tidal carbon dioxide monitoring provides continuous information about ventilation and the breathing circuit.","End-tidal CO₂ monitoring ले ventilation र breathing circuit बारे निरन्तर जानकारी दिन्छ।","Anaesthesia Monitoring"],["A sudden fall in end-tidal CO₂ during surgery may indicate which serious event?","Operation चल्दा end-tidal CO₂ अचानक घटेमा कुन गम्भीर अवस्था संकेत हुन सक्छ?",["Improved ventilation only","Disconnection or major fall in pulmonary blood flow","Increased body temperature","Normal recovery"],1,"A sudden ETCO₂ decrease can occur with circuit disconnection, cardiac output collapse or pulmonary embolism; assess the patient and equipment immediately.","ETCO₂ अचानक घट्नु circuit छुटेको, cardiac output घटेको वा pulmonary embolism को संकेत हुन सक्छ; बिरामी र उपकरण तुरुन्त जाँच्नुपर्छ।","Anaesthesia Monitoring"],["Which airway adjunct is inserted through the mouth to help maintain an airway in an unconscious patient without a gag reflex?","Gag reflex नभएको बेहोस बिरामीको airway खुला राख्न मुखबाट हालिने उपकरण कुन हो?",["Oropharyngeal airway","Nasal speculum","Mouth gag","Suction catheter only"],0,"An oropharyngeal airway helps prevent the tongue from obstructing the airway in an unconscious patient without an intact gag reflex.","Oropharyngeal airway ले gag reflex नभएको बेहोस बिरामीमा जिब्रोले airway बन्द गर्न नदिन मद्दत गर्छ।","Airway Management"],["Which position is commonly used for spinal anaesthesia in an adult?","Adult मा spinal anaesthesia दिन सामान्यतया कुन position प्रयोग गरिन्छ?",["Lithotomy or sitting","Prone with neck extended only","Trendelenburg only","Standing"],0,"Spinal anaesthesia is commonly performed in sitting or lateral decubitus position with appropriate spinal flexion.","Spinal anaesthesia प्रायः बसेको वा करवट परेको अवस्थामा ढाड उपयुक्त रूपमा मोडेर दिइन्छ।","Anaesthesia Technique"],["Which drug is a commonly used intravenous induction agent for general anaesthesia?","General anaesthesia सुरु गर्न प्रयोग हुने सामान्य intravenous induction drug कुन हो?",["Propofol","Neostigmine","Atropine eye drops","Furosemide"],0,"Propofol is a widely used IV induction agent; dose and use depend on patient assessment and anaesthesia provider.","Propofol सामान्य IV induction agent हो; मात्रा बिरामीको अवस्था र anaesthesia provider को निर्णयअनुसार हुन्छ।","Anaesthesia Pharmacology"],["Which medicine is used to reverse non-depolarizing neuromuscular blockade?","Non-depolarizing neuromuscular blockade उल्ट्याउन कुन औषधि प्रयोग हुन्छ?",["Neostigmine with an antimuscarinic","Ketamine alone","Adrenaline alone","Lignocaine gel"],0,"Neostigmine increases acetylcholine at the neuromuscular junction and is commonly paired with an antimuscarinic to limit muscarinic effects.","Neostigmine ले neuromuscular junction मा acetylcholine बढाउँछ र muscarinic असर घटाउन antimuscarinic सँग दिइन्छ।","Anaesthesia Pharmacology"],["Which drug is the specific reversal agent for opioid-induced respiratory depression?","Opioid का कारण भएको respiratory depression उल्ट्याउन कुन औषधि प्रयोग गरिन्छ?",["Naloxone","Flumazenil","Vitamin K","Protamine"],0,"Naloxone is an opioid antagonist used to reverse opioid effects, with monitoring for recurrence of respiratory depression.","Naloxone opioid antagonist हो; असर फेरि देखिन सक्ने भएकाले बिरामीको निगरानी आवश्यक हुन्छ।","Anaesthesia Pharmacology"],["Which agent is used to reverse benzodiazepine effects in selected cases?","छानिएका अवस्थामा benzodiazepine को असर उल्ट्याउन कुन औषधि प्रयोग हुन्छ?",["Flumazenil","Naloxone","Atropine","Calcium gluconate"],0,"Flumazenil is a benzodiazepine receptor antagonist; its use requires caution because seizures or re-sedation may occur.","Flumazenil benzodiazepine receptor antagonist हो; seizure वा फेरि sedation हुन सक्ने भएकाले सावधानीपूर्वक प्रयोग गरिन्छ।","Anaesthesia Pharmacology"],["Which method is most appropriate to confirm tracheal tube placement after intubation?","Intubation पछि tracheal tube सही ठाउँमा छ भनी पुष्टि गर्ने सबैभन्दा उपयुक्त विधि कुन हो?",["Sustained waveform capnography","Chest movement alone","Tube misting alone","Auscultation of stomach only"],0,"Sustained waveform capnography is the preferred confirmation method, supported by clinical assessment and bilateral chest examination.","Sustained waveform capnography tube सही ठाउँमा भएको पुष्टि गर्ने मुख्य विधि हो; clinical assessment र दुवै छाती सुन्ने जाँच पनि गरिन्छ।","Airway Management"],["What is the recommended immediate action when a surgical count discrepancy is identified before wound closure?","घाउ बन्द गर्नुअघि surgical count नमिलेमा तुरुन्त के गर्नुपर्छ?",["Inform the surgeon and repeat/search the count systematically","Ignore it if the wound is small","Document it after discharge only","Close the wound quickly"],0,"A discrepancy must be communicated immediately; repeat the count, search the field and room, and follow the facility escalation and imaging policy.","Count नमिलेको कुरा तुरुन्त surgeon लाई बताउने, फेरि गन्ने, field र room खोज्ने तथा संस्थाको escalation र imaging policy पालना गर्ने।","Surgical Counts"],["Which indicator directly demonstrates that a sterilization process has achieved the required microbial kill under defined conditions?","निर्धारित अवस्थामा sterilization ले आवश्यक microbial kill गरेको प्रमाण दिने indicator कुन हो?",["Biological indicator","External tape colour only","Package label","Chemical storage log"],0,"Biological indicators use resistant bacterial spores and provide direct evidence of sterilization process lethality when used and interpreted correctly.","Biological indicator मा resistant bacterial spores प्रयोग हुन्छन् र सही प्रयोग/व्याख्यामा sterilization प्रभावकारिताको प्रत्यक्ष प्रमाण दिन्छ।","CSSD"],["Why should hinged surgical instruments be opened before steam sterilization?","Steam sterilization अघि hinged instrument किन खुला राख्नुपर्छ?",["To allow steam contact with all surfaces","To make the package heavier","To prevent drying","To shorten the instrument"],0,"Opening joints exposes surfaces to cleaning and sterilizing agents and reduces areas shielded from steam.","Joint खुला गर्दा सबै सतहमा cleaning र sterilizing agent पुग्न सजिलो हुन्छ।","CSSD"],["Which practice reduces the risk of needlestick injury during instrument handling?","Instrument चलाउँदा needlestick injury को जोखिम घटाउने अभ्यास कुन हो?",["Use a neutral zone or hands-free passing","Recap used needles with both hands","Leave sharps in linen","Pass sharp instruments point-first by hand"],0,"A neutral zone or hands-free technique reduces direct hand-to-hand passing of sharps; use approved sharps containers.","Neutral zone वा hands-free technique ले sharp वस्तु हातबाट हातमा पास गर्ने जोखिम घटाउँछ; approved sharps container प्रयोग गर्नुपर्छ।","OT Safety"],["Which statement about surgical hand antisepsis is correct?","Surgical hand antisepsis बारे कुन भनाइ सही हो?",["It reduces transient flora and suppresses resident flora for the procedure","It replaces sterile gloves","It is needed only after surgery","It is the same as a quick social hand wash"],0,"Surgical hand antisepsis uses an approved surgical hand rub or scrub according to product instructions and institutional policy.","Surgical hand antisepsis approved surgical hand rub वा scrub बाट product instruction र संस्थाको policy अनुसार गरिन्छ।","Aseptic Technique"],["What is the purpose of a surgical time-out immediately before incision?","Incision अघि गरिने surgical time-out को उद्देश्य के हो?",["Confirm correct patient, procedure and site with the team","Count the recovery room beds","Check the hospital menu","Replace informed consent"],0,"The team pauses to confirm patient identity, procedure, site and critical safety points before starting.","Operation सुरु गर्नुअघि team ले बिरामी, procedure, site र मुख्य safety point पुष्टि गर्छ।","Patient Safety"],["Which gas is commonly used to drive a pneumatic surgical drill?","Pneumatic surgical drill चलाउन सामान्यतया कुन gas प्रयोग हुन्छ?",["Compressed air or nitrogen as specified by equipment","Carbon dioxide from a soda bottle","Oxygen from a wall outlet without regulator","Nitrous oxide from any cylinder"],0,"Pneumatic equipment uses the gas and pressure specified by the manufacturer and facility engineering policy; never improvise connections.","Pneumatic उपकरणमा manufacturer र hospital engineering ले तोकेको gas र pressure मात्र प्रयोग गर्नुपर्छ; जथाभावी जोड्नु हुँदैन।","OT Equipment"],["Which colour change or reading should be used to decide whether a chemical indicator has passed?","Chemical indicator पास भयो कि भएन भन्ने निर्णय कसरी गर्नुपर्छ?",["Compare with the manufacturer's stated acceptance endpoint","Assume every colour change is a pass","Use the package size","Judge by smell"],0,"Interpret each indicator against its manufacturer-defined endpoint; a failed or uncertain indicator means the load must be held and investigated.","Indicator लाई manufacturer ले दिएको endpoint अनुसार जाँच्ने; fail वा शंका भए load रोक्ने र जाँच गर्ने।","CSSD"],["What is the principal purpose of a smoke evacuator during electrosurgery?","Electrosurgery गर्दा smoke evacuator को मुख्य उद्देश्य के हो?",["Remove surgical plume from the breathing zone","Increase cautery power","Cool the patient","Sterilize the wound"],0,"Surgical plume may contain irritants and biological material; local evacuation near the source reduces exposure.","Surgical plume मा irritant र जैविक पदार्थ हुन सक्छ; स्रोत नजिकबाट हटाउँदा exposure घट्छ।","OT Safety"],["Which instrument is primarily used to grasp delicate tissue atraumatically?","नरम tissue लाई कम चोट पुर्‍याएर समात्न कुन instrument प्रयोग गरिन्छ?",["Atraumatic forceps","Bone rongeur","Osteotome","Volkmann curette"],0,"Atraumatic forceps such as DeBakey-type forceps are designed to handle delicate tissue with less crushing injury.","DeBakey जस्ता atraumatic forceps ले नरम tissue लाई कम crush गरेर समात्न मद्दत गर्छ।","Surgical Instruments"],["Which instrument is commonly used to clamp a blood vessel temporarily?","रक्तनलीलाई अस्थायी रूपमा बन्द गर्न सामान्यतया कुन instrument प्रयोग हुन्छ?",["Artery forceps/hemostat","Retractor","Suction tip","Mayo scissors"],0,"A hemostat or artery forceps temporarily clamps a vessel to control bleeding; choose size and type for the tissue.","Hemostat वा artery forceps ले रक्तनली अस्थायी रूपमा च्यापेर bleeding नियन्त्रण गर्छ।","Surgical Instruments"],["Which action is appropriate if an electrosurgical return electrode alarm occurs?","Electrosurgical return electrode alarm आएमा के गर्नु उपयुक्त हुन्छ?",["Stop energy activation and check pad, cable and patient contact","Increase power immediately","Wet the pad with alcohol","Ignore the alarm"],0,"Stop activation and inspect the return electrode system and skin contact according to device instructions before resuming.","Energy प्रयोग रोक्ने र device instruction अनुसार pad, cable र छालासँगको contact जाँच्ने।","OT Equipment"],["Which finding is most consistent with local anaesthetic systemic toxicity (LAST)?","Local anaesthetic systemic toxicity (LAST) सँग कुन लक्षण बढी मिल्छ?",["Perioral numbness, tinnitus, seizure or cardiac instability","Isolated itchy toe","Improved appetite","Slow hair growth"],0,"LAST may begin with neurological symptoms such as circumoral numbness, tinnitus or seizures and progress to cardiovascular collapse; activate emergency protocol.","LAST मा मुख वरिपरि झमझम, कान बज्ने वा seizure हुन सक्छ र पछि मुटुको गम्भीर समस्या आउन सक्छ; emergency protocol सक्रिय गर्नुपर्छ।","Anaesthesia Emergencies"],["Which laboratory test is commonly used to estimate glomerular filtration?","मिर्गौलाको filtration अनुमान गर्न कुन test प्रयोग हुन्छ?",["Serum bilirubin","Bleeding time","Serum amylase","Serum creatinine with eGFR"],3,"Serum creatinine is used to estimate GFR; interpret with age, muscle mass and clinical context.","Serum creatinine बाट GFR अनुमान गरिन्छ; उमेर, मांसपेशी र clinical अवस्था पनि विचार गर्नुपर्छ।","Biochemistry"],["Which electrolyte is the major intracellular cation?","कोशिकाभित्रको मुख्य cation कुन हो?",["Sodium","Calcium","Potassium","Chloride"],2,"Potassium is the major intracellular cation; sodium is the major extracellular cation.","Potassium कोशिकाभित्रको मुख्य cation हो; sodium कोशिकाबाहिरको मुख्य cation हो।","Biochemistry"],["Which buffer system is a major regulator of extracellular blood pH?","Extracellular blood pH नियन्त्रण गर्ने मुख्य buffer system कुन हो?",["Bicarbonate buffer","Urea buffer","Glucose buffer","Cholesterol buffer"],0,"The bicarbonate-carbonic acid system is a major extracellular buffer regulated by lungs and kidneys.","Bicarbonate-carbonic acid system मुख्य extracellular buffer हो, जसलाई फोक्सो र मिर्गौलाले नियमन गर्छन्।","Biochemistry"],["Which substance is formed from ammonia in the liver to reduce toxicity?","Ammonia को विषाक्तता घटाउन कलेजोमा कुन पदार्थ बनाइन्छ?",["Creatinine","Urea","Bilirubin","Lactate"],1,"The urea cycle converts toxic ammonia into urea for renal excretion.","Urea cycle ले विषाक्त ammonia लाई urea मा बदल्छ र मिर्गौलाबाट बाहिर निकालिन्छ।","Biochemistry"],["Which organism is associated with tetanus?","Tetanus गराउने जीवाणु कुन हो?",["Vibrio cholerae","Escherichia coli","Streptococcus pyogenes","Clostridium tetani"],3,"Clostridium tetani produces a neurotoxin causing rigidity and muscle spasms.","Clostridium tetani ले neurotoxin बनाउँछ, जसले मांसपेशी कडा र ऐंठन गराउँछ।","Microbiology"],["Which fungus commonly causes oral thrush in susceptible patients?","जोखिम भएका बिरामीमा oral thrush गराउने सामान्य fungus कुन हो?",["Candida albicans","Shigella","Clostridium tetani","Salmonella"],0,"Candida species can cause oral and other mucosal infections, especially in susceptible patients.","Candida ले मुख र अन्य mucosa मा संक्रमण गराउन सक्छ, विशेषगरी जोखिम भएका बिरामीमा।","Microbiology"],["Which immunity is produced by vaccination?","खोप लगाएपछि कुन immunity विकास हुन्छ?",["Artificial active","Natural passive","Artificial passive","Innate only"],0,"Vaccination stimulates the person's own immune response, producing artificial active immunity.","खोपले व्यक्तिको आफ्नै immune response सक्रिय गराउँछ, त्यसैले artificial active immunity हुन्छ।","Microbiology"],["Which OT team member maintains the sterile field and passes instruments?","Sterile field कायम राख्ने र instrument पास गर्ने OT सदस्य को हो?",["Scrub person","Porter","Reception clerk","Dietitian"],0,"The scrub person works within the sterile field and passes instruments to the surgeon.","Scrub person sterile field भित्र रहेर surgeon लाई instrument पास गर्छ।","OT Teamwork"],["Which team member coordinates documentation and non-sterile supplies during surgery?","Operation चल्दा documentation र non-sterile supply समन्वय गर्ने सदस्य को हो?",["Circulating nurse","Scrub surgeon","Patient attendant","Pathology courier"],0,"The circulating nurse coordinates room activities, documentation and supplies outside the sterile field.","Circulating nurse sterile field बाहिर रहेर room activity, documentation र supply समन्वय गर्छ।","OT Teamwork"],["What is the function of an anaesthesia gas scavenging system?","Anaesthesia gas scavenging system को काम के हो?",["Remove waste anaesthetic gases","Deliver oxygen to patient","Measure blood glucose","Sterilize the circuit"],0,"Scavenging removes excess waste anaesthetic gases and reduces occupational exposure.","Scavenging ले अतिरिक्त waste anaesthetic gas हटाएर कर्मचारीको exposure घटाउँछ।","Medical Gases"],["Which local anaesthetic technique places medicine in the epidural space?","Epidural space मा औषधि दिने local anaesthetic विधि कुन हो?",["Epidural anaesthesia","Topical anaesthesia","General anaesthesia","Cryoanaesthesia"],0,"Epidural anaesthesia delivers medicine into the epidural space, often through a catheter.","Epidural anaesthesia मा epidural space भित्र औषधि दिइन्छ, प्रायः catheter मार्फत।","Regional Anaesthesia"],["Which drug group supports blood pressure through vasoconstriction in selected shock states?","केही shock अवस्थामा vasoconstriction मार्फत BP बढाउने औषधि समूह कुन हो?",["Vasopressors","Antihistamines","Antacids","Antifungals"],0,"Vasopressors such as norepinephrine support vascular tone under close monitoring.","Norepinephrine जस्ता vasopressor ले कडा monitoring मा vascular tone कायम गर्न मद्दत गर्छ।","Anaesthesia Pharmacology"],["Which parameter is directly estimated by pulse oximetry?","Pulse oximetry ले कुन parameter अनुमान गर्छ?",["Peripheral oxygen saturation","End-tidal CO₂","Blood glucose","Haemoglobin concentration"],0,"Pulse oximetry estimates peripheral oxygen saturation and pulse rate, not ventilation directly.","Pulse oximetry ले oxygen saturation र pulse rate अनुमान गर्छ; ventilation प्रत्यक्ष मापन गर्दैन।","Patient Monitoring"],["Which imaging modality uses magnetic fields rather than ionizing X-rays?","Ionizing X-ray नभई magnetic field प्रयोग गर्ने imaging कुन हो?",["MRI","CT scan","Plain radiograph","Fluoroscopy"],0,"MRI uses magnetic fields and radiofrequency pulses, not ionizing radiation.","MRI ले magnetic field र radiofrequency pulse प्रयोग गर्छ; ionizing radiation होइन।","Diagnostic Procedures"],["Which operation removes the spleen?","प्लीहा हटाउने operation कुन हो?",["Gastrectomy","Hepatectomy","Pancreatectomy","Splenectomy"],3,"Splenectomy is surgical removal of the spleen; infection prevention and vaccination planning are important afterward.","Splenectomy मा प्लीहा हटाइन्छ; त्यसपछि संक्रमण रोकथाम र vaccination योजना महत्वपूर्ण हुन्छ।","General Surgery"],["Which rhythm is shockable during adult cardiac arrest?","वयस्क cardiac arrest मा कुन rhythm shockable हुन्छ?",["Ventricular fibrillation","Asystole","Pulseless electrical activity","Normal sinus rhythm"],0,"Ventricular fibrillation and pulseless ventricular tachycardia are shockable rhythms; asystole and PEA are not.","Ventricular fibrillation र pulseless VT shockable rhythm हुन्; asystole र PEA shockable होइनन्।","CPR"],["For an adult with cardiac arrest, what is the recommended chest compression rate?","वयस्क cardiac arrest मा chest compression को सिफारिस गरिएको गति कति हो?",["100–120 per minute","40–60 per minute","60–80 per minute","More than 160 per minute"],0,"Adult CPR uses a compression rate of 100–120 per minute with adequate depth and full recoil.","Adult CPR मा प्रति मिनेट 100–120 compression, पर्याप्त गहिराइ र पूर्ण recoil आवश्यक हुन्छ।","CPR"],["What is the recommended adult chest compression depth?","वयस्कमा chest compression को सिफारिस गरिएको गहिराइ कति हो?",["At least 5 cm but not more than 6 cm","1 cm","2 cm","8–10 cm"],0,"For most adults, compress at least 5 cm while avoiding excessive depth beyond 6 cm.","वयस्कमा कम्तीमा 5 cm तर 6 cm भन्दा बढी नहुने गरी compression गरिन्छ।","CPR"],["When an AED arrives during cardiac arrest, the team should:","Cardiac arrest हुँदा AED आइपुगेपछि के गर्नुपर्छ?",["Apply it promptly and follow its voice prompts while minimizing interruptions","Wait until CPR has stopped for several minutes","Ignore it if a manual pulse is not felt","Use it only after transport"],0,"Attach the AED as soon as available, follow prompts and resume compressions immediately after shock/no-shock advice.","AED छिटो जोडेर निर्देशन पालना गर्ने र shock/no-shock पछि तुरुन्त compression सुरु गर्ने।","CPR"],["Which IV fluid is an example of an isotonic crystalloid?","Isotonic crystalloid को उदाहरण कुन हो?",["0.9% sodium chloride","10% dextrose","3% sodium chloride","Albumin"],0,"0.9% sodium chloride is an isotonic crystalloid commonly used when clinically indicated.","0.9% sodium chloride isotonic crystalloid हो र आवश्यक clinical अवस्थामा प्रयोग गरिन्छ।","Fluids"],["Which is an example of a colloid solution?","Colloid solution को उदाहरण कुन हो?",["Albumin","0.9% saline","Ringer's lactate","5% dextrose in water"],0,"Albumin is a colloid; fluid choice depends on indication, risks and current guidance.","Albumin colloid हो; fluid छनोट indication, जोखिम र guideline अनुसार हुन्छ।","Fluids"],["Which blood group is the universal red-cell donor in emergency uncrossmatched transfusion?","Emergency मा crossmatch नभएको अवस्थामा red-cell transfusion का लागि universal donor कुन हो?",["O negative","AB positive","A positive","B negative"],0,"O-negative red cells are commonly used for emergency uncrossmatched transfusion when indicated, following transfusion policy.","आवश्यक emergency अवस्थामा policy अनुसार O-negative red cells प्रयोग गरिन्छ।","Blood Transfusion"],["Which test is performed before a planned blood transfusion to assess compatibility?","नियोजित blood transfusion अघि compatibility जाँच्न कुन परीक्षण गरिन्छ?",["Crossmatch","Urine culture","Liver biopsy","Skin prick test"],0,"Crossmatching checks compatibility between donor red cells and recipient plasma before transfusion.","Crossmatch ले donor red cells र recipient plasma बीच compatibility जाँच्छ।","Blood Transfusion"],["Fever, chills, back pain or hypotension during transfusion may indicate:","Transfusion चल्दा ज्वरो, काँप्ने, ढाड दुख्ने वा hypotension भएमा के शंका गर्नुपर्छ?",["Transfusion reaction","Normal expected response","Improved oxygenation","Simple hunger"],0,"Stop the transfusion immediately, maintain IV access with appropriate fluid per protocol, assess the patient and notify the responsible clinician/blood bank.","Transfusion तुरुन्त रोक्ने, protocol अनुसार IV access कायम गर्ने, बिरामी जाँच्ने र जिम्मेवार clinician/blood bank लाई खबर गर्ने।","Blood Transfusion"],["Which blood component is primarily used to improve oxygen-carrying capacity?","Oxygen बोक्ने क्षमता बढाउन मुख्य रूपमा कुन blood component दिइन्छ?",["Packed red blood cells","Platelet concentrate","Fresh frozen plasma","Cryoprecipitate"],0,"Packed red blood cells increase haemoglobin and oxygen-carrying capacity when transfusion is indicated.","आवश्यक अवस्थामा packed red cells ले haemoglobin र oxygen बोक्ने क्षमता बढाउँछ।","Blood Transfusion"],["Which action is essential before administering any medication?","कुनै औषधि दिनुअघि कुन कार्य अनिवार्य छ?",["Verify patient, medicine, dose, route, time, allergy and order","Assume the label is correct","Use another patient's chart","Skip documentation"],0,"Medication safety includes patient identification, correct drug/dose/route/time, allergy checks and documentation.","औषधि सुरक्षा लागि बिरामी, औषधि, मात्रा, route, समय, allergy र documentation जाँचिन्छ।","Patient Safety"],["What is the primary purpose of informed consent?","Informed consent को मुख्य उद्देश्य के हो?",["Support an informed, voluntary decision by the patient","Transfer all clinical responsibility to the patient","Replace explanation","Permit procedures without identification"],0,"Consent follows adequate information about the procedure, material risks, benefits and alternatives, and must be voluntary.","Procedure, जोखिम, फाइदा र विकल्पबारे जानकारी पाएपछि बिरामीले स्वेच्छाले निर्णय गर्नु consent हो।","Medico-legal"],["Which record is important for legal accountability in the operating room?","OT मा कानुनी जवाफदेहिताका लागि कुन अभिलेख महत्त्वपूर्ण हुन्छ?",["Accurate contemporaneous patient and procedure documentation","Undated personal notes only","Verbal memory alone","Blank checklist"],0,"Clear, timely and accurate records support continuity, safety and accountability.","स्पष्ट, समयमै र सही documentation ले continuity, safety र accountability कायम गर्छ।","Medico-legal"],["Which position is commonly used for pelvic and perineal procedures?","Pelvic र perineal procedure मा सामान्यतया कुन position प्रयोग हुन्छ?",["Lithotomy","Prone","Sitting","Jackknife for every procedure"],0,"Lithotomy provides access to the perineum; protect pressure points and avoid excessive hip flexion/abduction.","Lithotomy ले perineum मा पहुँच दिन्छ; pressure points जोगाउने र hip अत्यधिक मोड्न/फैलाउन हुँदैन।","Positioning"],["Which complication is associated with prolonged pressure over the common peroneal nerve in lithotomy?","Lithotomy मा common peroneal nerve मा लामो दबाब परेमा कुन complication हुन सक्छ?",["Foot drop","Cataract","Hearing loss","Jaundice"],0,"Common peroneal nerve compression can cause weakness of ankle dorsiflexion and foot drop.","Common peroneal nerve थिचिँदा खुट्टाको dorsiflexion कमजोर भएर foot drop हुन सक्छ।","Positioning"],["Which position may be used for some thyroid and anterior neck operations?","केही thyroid र अगाडिको घाँटीको operation मा कुन position प्रयोग हुन सक्छ?",["Supine with neck appropriately extended","Prone with neck flexed","Lithotomy","Trendelenburg in all cases"],0,"Supine with carefully supported neck extension may improve access; avoid excessive extension and protect the airway.","Supine मा घाँटीलाई सावधानीपूर्वक extend गर्दा पहुँच सजिलो हुन्छ; अत्यधिक extension नगर्नुहोस्।","Positioning"],["Why is an electrosurgical return electrode used in monopolar electrosurgery?","Monopolar electrosurgery मा return electrode किन प्रयोग गरिन्छ?",["To complete the electrical circuit and disperse current safely","To sterilize the instrument","To measure blood pressure","To provide oxygen"],0,"The return electrode completes the circuit and spreads current over a large area to reduce thermal injury risk.","Return electrode ले circuit पूरा गर्छ र current ठूलो क्षेत्रमा फैलाएर burn जोखिम घटाउँछ।","OT Equipment"],["What is a key safety precaution when using electrosurgery?","Electrosurgery प्रयोग गर्दा मुख्य safety precaution के हो?",["Keep alcohol-based prep fully dry and manage oxygen/fire risk","Use it beside pooled alcohol prep","Ignore the return electrode","Place drapes over active electrode tips"],0,"Allow alcohol-based skin preparation to dry fully, prevent pooling and coordinate oxygen delivery to reduce surgical fire risk.","Alcohol-based skin prep पूर्ण सुक्न दिनु, जम्मा हुन नदिनु र oxygen व्यवस्थापन गर्नु surgical fire जोखिम घटाउने उपाय हुन्।","OT Equipment"],["Which instrument is used to view the urinary bladder endoscopically?","Urinary bladder भित्र endoscope बाट हेर्न कुन instrument प्रयोग हुन्छ?",["Cystoscope","Bronchoscope","Gastroscope","Arthroscope"],0,"Cystoscopy uses a cystoscope to examine the urethra and bladder and may allow selected procedures.","Cystoscope ले urethra र bladder हेर्न तथा केही procedure गर्न मद्दत गर्छ।","Urology"],["Which procedure removes the uterus?","Uterus हटाउने operation कुन हो?",["Hysterectomy","Oophorectomy","Cystectomy","Colectomy"],0,"Hysterectomy is surgical removal of the uterus; the approach depends on clinical indication.","Hysterectomy मा uterus हटाइन्छ; विधि clinical indication अनुसार छानिन्छ।","Gynaecology"],["Which procedure repairs a torn ligament?","च्यातिएको ligament मर्मत गर्ने procedure कुन हो?",["Ligament repair/reconstruction","Gastrectomy","Cataract extraction","Nephrostomy"],0,"Ligament repair or reconstruction restores stability depending on the injury and joint.","Ligament repair/reconstruction ले चोट र joint अनुसार स्थिरता पुनःस्थापित गर्छ।","Orthopaedics"],["Which instrument is commonly used to inspect the bronchial tree?","Bronchial tree निरीक्षण गर्न कुन instrument प्रयोग हुन्छ?",["Bronchoscope","Cystoscope","Colonoscope","Otoscope"],0,"Bronchoscopy allows visualization of the trachea and bronchi and may be diagnostic or therapeutic.","Bronchoscopy बाट trachea र bronchi हेर्न तथा आवश्यक procedure गर्न सकिन्छ।","Thoracic/ENT"],["Which operation creates an opening in the trachea?","Trachea मा opening बनाउने operation कुन हो?",["Tracheostomy","Thoracotomy","Laparotomy","Craniotomy"],0,"Tracheostomy creates an opening into the trachea to establish an airway when indicated.","Tracheostomy मा आवश्यक अवस्थामा airway बनाउन trachea मा opening बनाइन्छ।","ENT"],["Which procedure is used to remove a kidney?","मिर्गौला हटाउने operation कुन हो?",["Nephrectomy","Cystoscopy","Herniorrhaphy","Colectomy"],0,"Nephrectomy is surgical removal of all or part of a kidney, depending on the procedure.","Nephrectomy मा procedure अनुसार मिर्गौलाको केही वा सबै भाग हटाइन्छ।","Urology"],["Which procedure is commonly used to remove a breast?","स्तन हटाउने operation कुन हो?",["Mastectomy","Myringotomy","Splenectomy","Thyroidectomy"],0,"Mastectomy is surgical removal of breast tissue; the extent depends on the indication.","Mastectomy मा indication अनुसार breast tissue हटाइन्छ।","General Surgery"],["Which procedure creates an opening into the abdomen to access abdominal organs?","पेटका अंगमा पहुँचका लागि abdomen खोल्ने incision/procedure कुन हो?",["Laparotomy","Thoracotomy","Craniotomy","Arthroscopy"],0,"Laparotomy is an abdominal incision to access the peritoneal cavity and abdominal organs.","Laparotomy भनेको पेट खोलेर peritoneal cavity र abdominal organs मा पहुँच बनाउनु हो।","General Surgery"],["Which surgical procedure is used to remove the spleen?","Spleen हटाउने operation कुन हो?",["Splenectomy","Pancreatectomy","Appendectomy","Thyroidectomy"],0,"Splenectomy is surgical removal of the spleen; infection prevention and vaccination planning are important after total splenectomy.","Splenectomy मा spleen हटाइन्छ; total splenectomy पछि संक्रमण रोकथाम र vaccination योजना महत्त्वपूर्ण हुन्छ।","General Surgery"],["Which procedure is used to replace a diseased heart valve?","बिरामी भएको heart valve बदल्ने procedure कुन हो?",["Heart valve replacement","Appendectomy","Cystoscopy","Myringotomy"],0,"Valve replacement substitutes a diseased valve with a prosthetic valve when indicated.","आवश्यक अवस्थामा खराब valve लाई prosthetic valve ले बदलिन्छ।","Cardiac Surgery"],["What does CABG stand for?","CABG को पूरा रूप के हो?",["Coronary artery bypass grafting","Central airway balloon guidance","Cardiac atrial blood grouping","Coronary angiographic biopsy"],0,"CABG creates a bypass route around narrowed coronary arteries to improve myocardial blood supply.","CABG ले साँघुरिएको coronary artery वरिपरि bypass बाटो बनाएर मुटुको मांसपेशीमा रगत पुर्‍याउँछ।","Cardiac Surgery"],["Which instrument is used to view the inside of a joint?","Joint भित्र हेर्न कुन instrument प्रयोग हुन्छ?",["Arthroscope","Bronchoscope","Cystoscope","Otoscope"],0,"Arthroscopy uses a small camera to visualize a joint and perform selected minimally invasive procedures.","Arthroscope सानो camera हो जसबाट joint भित्र हेरेर केही minimally invasive procedure गरिन्छ।","Orthopaedics"],["Which complication is characterized by widespread activation of coagulation with consumption of platelets and clotting factors?","Platelet र clotting factor खपत हुँदै व्यापक coagulation सक्रिय हुने complication कुन हो?",["Disseminated intravascular coagulation (DIC)","Simple bruising only","Atelectasis","Hypothermia"],0,"DIC is a serious acquired syndrome involving systemic coagulation activation, microthrombi and bleeding due to factor consumption.","DIC मा शरीरभर coagulation सक्रिय भई microthrombi बन्ने र factor खपतका कारण bleeding हुन सक्छ।","Complications"],["Which postoperative finding may indicate wound dehiscence?","Postoperative wound dehiscence को संकेत कुन हुन सक्छ?",["Separation of wound edges","Normal scar maturation","Mild expected bruising only","Hair growth"],0,"Wound dehiscence is partial or complete separation of previously closed wound edges and requires urgent clinical assessment.","बन्द गरिएको घाउका किनारा आंशिक वा पूर्ण छुट्टिनु wound dehiscence हो; तुरुन्त clinical assessment चाहिन्छ।","Complications"],["A patient becomes suddenly breathless after surgery with chest pain and low oxygen saturation. Which serious complication should be considered?","Surgery पछि अचानक सास फेर्न गाह्रो, छाती दुख्ने र oxygen कम भएमा कुन गम्भीर complication सोच्नुपर्छ?",["Pulmonary embolism","Simple wound itch","Cataract","Otitis externa"],0,"Pulmonary embolism is a potentially life-threatening cause of acute postoperative dyspnoea and requires urgent evaluation.","Pulmonary embolism postoperative acute dyspnoea को जीवन जोखिमपूर्ण कारण हुन सक्छ; तुरुन्त जाँच चाहिन्छ।","Complications"],["Which practice helps prevent retained surgical items?","Surgery पछि वस्तु शरीरभित्र छुट्न नदिन कुन अभ्यास उपयोगी हुन्छ?",["Standardized counts, reconciliation and documented handover","Estimate by memory","Count only after skin closure","Discard count records"],0,"Standardized counts at required stages, discrepancy escalation and documentation reduce retained-item risk.","निर्धारित चरणमा count, फरक परे escalation र documentation ले retained item जोखिम घटाउँछ।","Patient Safety"],["What is the purpose of an ultrasonic bath for instruments?","Instrument सफा गर्दा ultrasonic bath को उद्देश्य के हो?",["Dislodge soil from hard-to-reach surfaces by cavitation","Sterilize every instrument automatically","Replace inspection and packaging","Sharpen cutting edges"],0,"Ultrasonic cleaning uses cavitation to help remove debris from joints and crevices; it does not replace rinsing, inspection and sterilization.","Ultrasonic cavitation ले joint/crevice बाट मैलो हटाउन मद्दत गर्छ; यसले rinsing, inspection र sterilization प्रतिस्थापन गर्दैन।","Practical Skills"],["What should be done with a visibly dirty reusable instrument before sterilization?","दृश्य रूपमा फोहोर reusable instrument sterilization अघि के गर्नुपर्छ?",["Clean it thoroughly according to validated instructions","Wrap it without cleaning","Wipe only the handle","Put it directly into storage"],0,"Cleaning removes organic/inorganic soil that can interfere with disinfection or sterilization; follow validated device instructions.","Cleaning ले मैलो हटाउँछ, जसले disinfection/sterilization मा बाधा पुर्‍याउन सक्छ; validated निर्देश पालना गर्नुपर्छ।","Practical Skills"],["Which method is appropriate for sterilizing a heat-sensitive flexible endoscope?","Heat-sensitive flexible endoscope sterilize गर्न कुन विधि उपयुक्त हुन्छ?",["A validated low-temperature process compatible with the device","Routine dry heat at very high temperature","Boiling for one minute","Wiping with plain water"],0,"Use a validated high-level disinfection or sterilization process as required by device classification and manufacturer instructions; many flexible endoscopes are heat-sensitive.","Device classification र manufacturer निर्देशअनुसार validated high-level disinfection वा sterilization प्रयोग गर्नुपर्छ; धेरै flexible endoscope heat-sensitive हुन्छन्।","Practical Skills"],["Which waste category should a blood-soaked dressing generally enter under a colour-coded healthcare waste system?","रगतले भिजेको dressing लाई सामान्यतया कुन waste category मा राखिन्छ?",["Infectious/soiled clinical waste according to local colour code","General recyclable paper","Food waste","Uncontaminated glass"],0,"Segregate blood-contaminated dressings as infectious waste using the applicable national and facility colour code.","रगत लागेको dressing लाई राष्ट्रिय तथा संस्थागत colour code अनुसार infectious waste मा छुट्याउनुपर्छ।","Practical Skills"],["Which check is important before using an anaesthesia breathing circuit?","Anaesthesia breathing circuit प्रयोग गर्नुअघि कुन जाँच महत्त्वपूर्ण हुन्छ?",["Leak and function check according to machine checklist","Check only the colour","Assume it is safe if recently stored","Disconnect the oxygen supply"],0,"A pre-use machine and breathing-system check identifies leaks, disconnections and malfunction before patient connection.","Pre-use machine र breathing system check ले बिरामी जोड्नुअघि leak, disconnection र खराबी पत्ता लगाउँछ।","Practical Skills"],["Which device is used to deliver a controlled concentration of oxygen to a patient?","बिरामीलाई नियन्त्रित oxygen concentration दिन कुन उपकरण प्रयोग गरिन्छ?",["Oxygen delivery system with an appropriate interface","Surgical retractor","Suction jar","Electrosurgical pencil"],0,"Oxygen delivery devices are selected based on the required flow, concentration and patient condition.","आवश्यक flow, concentration र बिरामीको अवस्थाअनुसार oxygen delivery device छानिन्छ।","Anaesthesia Equipment"],["Which instrument is commonly used to retract soft tissue during an operation?","Operation गर्दा soft tissue तानिराख्न कुन instrument प्रयोग हुन्छ?",["Surgical retractor","Suture needle","Artery forceps only","Bone drill"],0,"Retractors hold tissues aside to improve exposure; the type and pressure should suit the tissue.","Retractor ले tissue हटाएर operation site देखाउँछ; tissue अनुसार सही प्रकार र दबाब प्रयोग गर्नुपर्छ।","Surgical Instruments"],["Which drain is a closed-suction system commonly used to remove postoperative fluid?","Operation पछि तरल निकाल्न प्रयोग हुने closed-suction drain कुन हो?",["Jackson-Pratt drain","T-tube","Penrose drain","Chest retractor"],0,"A Jackson-Pratt drain uses a compressed bulb to provide gentle closed suction and collect fluid.","Jackson-Pratt drain मा compressed bulb ले हल्का suction बनाएर तरल संकलन गर्छ।","Postoperative Drains"],["Which instrument is designed to hold a suture needle?","Suture needle समात्न कुन instrument बनाइएको हो?",["Needle holder","Towel clip","Sponge forceps","Bone curette"],0,"A needle holder securely grips the surgical needle during suturing.","Needle holder ले suturing गर्दा surgical needle सुरक्षित रूपमा समात्छ।","Surgical Instruments"],["Which action is appropriate when a surgical count discrepancy occurs?","Surgical count नमिलेमा उपयुक्त कदम के हो?",["Immediately inform the team, repeat/reconcile the count and follow policy before closure","Ignore the discrepancy","Document a correct count without checking","Dispose of all used sponges"],0,"A discrepancy must be communicated and investigated promptly, with systematic search and escalation under facility policy.","Count नमिलेमा तुरुन्त जानकारी दिई फेरि जाँच/मिलान गर्ने र संस्थाको policy अनुसार खोज तथा escalation गर्नुपर्छ।","OT Safety"],["Which gas is commonly used to create pneumoperitoneum in laparoscopy?","Laparoscopy मा pneumoperitoneum बनाउन कुन gas प्रयोग हुन्छ?",["Oxygen","Carbon dioxide","Nitrogen","Nitrous oxide"],1,"Carbon dioxide is commonly used because it is non-flammable and readily absorbed.","Carbon dioxide नजल्ने र शरीरले सजिलै absorb गर्ने भएकाले प्रयोग हुन्छ।","Laparoscopy"],["What is the purpose of a laparoscope?","Laparoscope को मुख्य काम के हो?",["Visualize the abdominal cavity","Measure blood pressure","Deliver oxygen","Sterilize instruments"],0,"A laparoscope provides a camera view of the abdominal cavity through small ports.","Laparoscope ले सानो port बाट पेटभित्रको दृश्य camera मा देखाउँछ।","Laparoscopy"],["Which procedure removes obstructing prostate tissue through the urethra?","Urethra बाट prostate को अवरोध गर्ने tissue हटाउने procedure कुन हो?",["TURP","Nephrectomy","Cystectomy","Ureteroscopy"],0,"Transurethral resection of the prostate (TURP) removes prostate tissue using an endoscopic instrument passed through the urethra.","TURP मा urethra हुँदै endoscopic instrument लगेर prostate को आवश्यक tissue हटाइन्छ।","Urology"],["Which phase of wound healing includes granulation tissue formation?","Granulation tissue बन्ने wound healing phase कुन हो?",["Proliferative","Haemostasis only","Maturation only","Initial injury"],0,"The proliferative phase includes angiogenesis, fibroblast activity and granulation tissue formation.","Proliferative phase मा नयाँ रक्तनली, fibroblast activity र granulation tissue बन्छ।","Wound Care"],["Which suture material is absorbable?","कुन suture material absorbable हो?",["Nylon","Polypropylene","Polyglactin 910","Silk"],2,"Polyglactin 910 is a synthetic absorbable braided suture.","Polyglactin 910 synthetic absorbable braided suture हो।","Suturing"],["A postoperative wound edge separation is called:","Operation पछि घाउको किनारा छुट्टिनुलाई के भनिन्छ?",["Dehiscence","Haemostasis","Intubation","Insufflation"],0,"Wound dehiscence is partial or complete separation of previously closed wound edges.","पहिले बन्द गरिएको घाउको किनारा आंशिक वा पूर्ण छुट्टिनु dehiscence हो।","Complications"],["Which membrane surrounds the lungs?","फोक्सोलाई घेर्ने membrane कुन हो?",["Pleura","Peritoneum","Pericardium","Meninges"],0,"The pleura is the serous membrane surrounding each lung.","Pleura ले प्रत्येक फोक्सोलाई घेर्छ।","Anatomy"],["Which part of the brainstem contains vital respiratory and cardiovascular centres?","श्वासप्रश्वास र cardiovascular केन्द्र भएको brainstem को भाग कुन हो?",["Medulla oblongata","Cerebellum","Occipital lobe","Corpus callosum"],0,"The medulla contains important autonomic centres for breathing and circulation.","Medulla मा श्वास र रक्तसञ्चारका महत्त्वपूर्ण autonomic केन्द्र हुन्छन्।","Anatomy"],["Which electrolyte disturbance is especially associated with peaked T waves on ECG?","ECG मा peaked T wave कुन electrolyte disturbance मा देखिन सक्छ?",["Hyperkalaemia","Hypocalcaemia","Hyponatraemia","Hypochloraemia"],0,"Hyperkalaemia can cause peaked T waves and dangerous conduction abnormalities.","Hyperkalaemia ले peaked T wave र खतरनाक conduction समस्या गराउन सक्छ।","Biochemistry"],["Which blood group is commonly called the universal red-cell donor type?","Universal red-cell donor भनेर कुन blood group लाई भनिन्छ?",["O negative","AB positive","A positive","B negative"],0,"O negative red cells lack A, B and Rh(D) antigens; emergency use still follows transfusion policy.","O negative red cells मा A, B र Rh(D) antigen हुँदैन; transfusion policy पालना गर्नुपर्छ।","Transfusion"],["Which organism is a common cause of urinary tract infection?","Urinary tract infection को सामान्य कारण कुन जीवाणु हो?",["Escherichia coli","Clostridium tetani","Mycobacterium leprae","Plasmodium falciparum"],0,"E. coli is a frequent cause of community and healthcare-associated UTI.","E. coli UTI को सामान्य कारण हो।","Microbiology"],["Which precaution is most appropriate for blood and body-fluid exposure?","रगत र body fluid exposure रोक्न कुन precaution उपयुक्त छ?",["Standard precautions","Airborne precautions only","No gloves needed","Protective isolation for every patient"],0,"Standard precautions apply to all patients and include hand hygiene and risk-based PPE.","सबै बिरामीमा standard precaution लागू हुन्छ; hand hygiene र जोखिमअनुसार PPE चाहिन्छ।","Infection Control"],["What is the main purpose of hand hygiene before an aseptic procedure?","Aseptic procedure अघि hand hygiene को मुख्य उद्देश्य के हो?",["Reduce transmission of microorganisms","Sterilize the whole room","Replace sterile gloves","Remove the need for cleaning"],0,"Hand hygiene reduces microorganism transmission and is essential before aseptic tasks.","Hand hygiene ले microorganism सर्ने जोखिम घटाउँछ।","Infection Control"],["Which item is semi-critical and requires at least high-level disinfection when sterilization is not feasible?","Sterilization सम्भव नभए कम्तीमा high-level disinfection चाहिने semi-critical item कुन हो?",["Device contacting mucous membrane","Device entering sterile tissue","Bedside table","Blood pressure cuff"],0,"Semi-critical devices contact mucous membranes or non-intact skin and require high-level disinfection at minimum.","Mucous membrane वा बिग्रिएको छालामा छुने semi-critical device लाई कम्तीमा high-level disinfection चाहिन्छ।","CSSD"],["What does a Bowie-Dick test assess in a pre-vacuum steam sterilizer?","Pre-vacuum steam sterilizer मा Bowie-Dick test ले के जाँच्छ?",["Air removal and steam penetration","Instrument sharpness","Water hardness only","Package weight"],0,"The Bowie-Dick test evaluates air removal and steam penetration in suitable pre-vacuum sterilizers.","Bowie-Dick test ले pre-vacuum sterilizer मा air removal र steam penetration जाँच्छ।","CSSD"],["Which action is appropriate after a count discrepancy is identified?","Count नमिलेमा उपयुक्त कदम के हो?",["Inform the surgeon/team and search systematically before closure per policy","Ignore it if wound is small","Document only after discharge","Add an item to the count sheet without checking"],0,"A discrepancy must be announced, investigated and escalated according to policy.","Count नमिलेको कुरा घोषणा गरी protocol अनुसार खोजी र escalation गर्नुपर्छ।","OT Technique"],["Which instrument is used to grasp a sponge for skin preparation?","Skin preparation का लागि sponge समात्न कुन instrument प्रयोग हुन्छ?",["Sponge-holding forceps","Needle holder","Bone cutter","Allis forceps only"],0,"Sponge-holding forceps hold gauze or sponges during preparation.","Sponge-holding forceps ले preparation गर्दा gauze वा sponge समात्छ।","Instruments"],["Which position may be used for kidney surgery?","Kidney surgery मा कुन position प्रयोग हुन सक्छ?",["Lateral kidney position","Lithotomy only","Trendelenburg only","Sitting"],0,"A lateral kidney position may provide access to the flank; pressure and alignment need care.","Lateral kidney position ले flank access दिन्छ; pressure र alignment सुरक्षित गर्नुपर्छ।","Positioning"],["Which anaesthetic agent is a volatile inhalational agent?","Volatile inhalational anaesthetic agent कुन हो?",["Sevoflurane","Propofol","Ketamine","Etomidate"],0,"Sevoflurane is a volatile inhalational anaesthetic.","Sevoflurane volatile inhalational anaesthetic हो।","Pharmacology"],["Which medicine is an anticholinergic sometimes used to reduce secretions or treat bradycardia?","Secretions घटाउन वा bradycardia मा कहिलेकाहीँ प्रयोग हुने anticholinergic कुन हो?",["Atropine","Furosemide","Warfarin","Amoxicillin"],0,"Atropine blocks muscarinic receptors and has selected perioperative uses.","Atropine ले muscarinic receptor block गर्छ र केही perioperative अवस्थामा प्रयोग हुन्छ।","Pharmacology"],["Which monitor records the electrical activity of the heart?","मुटुको electrical activity record गर्ने monitor कुन हो?",["ECG","Pulse oximeter","Capnograph","Temperature probe"],0,"ECG displays cardiac electrical activity and helps identify rhythm changes.","ECG ले मुटुको electrical activity र rhythm परिवर्तन देखाउँछ।","Monitoring"],["Which parameter is directly measured by a non-invasive blood pressure cuff?","Non-invasive blood pressure cuff ले कुन parameter मापन गर्छ?",["Arterial blood pressure","End-tidal CO2","Haemoglobin","Core temperature"],0,"An NIBP cuff estimates systolic and diastolic blood pressure.","NIBP cuff ले systolic र diastolic blood pressure अनुमान गर्छ।","Monitoring"],["Which event is a common early sign of inadequate anaesthetic depth during surgery?","Surgery मा anaesthesia गहिराइ अपर्याप्त भएको प्रारम्भिक संकेत कुन हुन सक्छ?",["Movement or autonomic response such as tachycardia/hypertension","Hair growth","Low urine colour","Nail discolouration"],0,"Movement and autonomic responses may indicate inadequate anaesthetic depth and require clinician assessment.","Movement र autonomic response anaesthesia कम भएको संकेत हुन सक्छ; clinician ले जाँच्नुपर्छ।","Anaesthesia"],["Which action is important when a patient is suspected to have malignant hyperthermia?","Malignant hyperthermia शंका हुँदा कुन काम महत्त्वपूर्ण हुन्छ?",["Stop triggering agents and activate emergency protocol","Continue volatile agent","Delay calling for help","Apply cold alcohol only"],0,"Stop triggers, call for help, administer dantrolene and follow the emergency protocol.","Trigger रोक्ने, सहयोग बोलाउने, dantrolene दिने र emergency protocol पालना गर्ने।","Emergency"],["Which drug is used to treat malignant hyperthermia?","Malignant hyperthermia उपचारमा कुन औषधि प्रयोग हुन्छ?",["Dantrolene","Naloxone","Flumazenil","Protamine"],0,"Dantrolene reduces skeletal muscle calcium release and is the specific treatment.","Dantrolene ले skeletal muscle बाट calcium release घटाउँछ र specific उपचार हो।","Pharmacology"],["Which transfusion complication is related to bacterial contamination of a blood component?","Blood component मा bacterial contamination हुँदा कुन complication हुन सक्छ?",["Septic transfusion reaction","TACO","TRALI","Iron deficiency"],0,"Bacterial contamination may cause fever, rigors, hypotension and sepsis.","Bacterial contamination ले ज्वरो, काम्ने, hypotension र sepsis गराउन सक्छ।","Transfusion"],["Which condition is a hallmark of TRALI?","TRALI को मुख्य विशेषता कुन हो?",["Acute hypoxaemia with non-cardiogenic pulmonary oedema","Fluid overload due to cardiac failure only","Delayed isolated rash","High blood glucose"],0,"TRALI causes acute lung injury and hypoxaemia without primary circulatory overload.","TRALI मा मुख्य volume overload बिना acute lung injury र hypoxaemia हुन्छ।","Transfusion"],["Which sign may help distinguish TACO from TRALI?","TACO र TRALI छुट्याउन कुन संकेत उपयोगी हुन सक्छ?",["Evidence of circulatory volume overload","Both always have identical cause","TACO never causes breathing difficulty","TRALI always causes hypertension"],0,"TACO is associated with hydrostatic pulmonary oedema and volume overload; full assessment is required.","TACO मा volume overload र hydrostatic pulmonary oedema हुन्छ; पूर्ण मूल्याङ्कन आवश्यक छ।","Transfusion"],["Which solution is commonly used to prime blood administration tubing?","Blood administration tubing prime गर्न सामान्यतया कुन solution प्रयोग हुन्छ?",["0.9% normal saline","Dextrose 5%","Ringer lactate in all protocols","Sterile water"],0,"Normal saline is commonly used with blood components; follow the blood bank and facility policy.","Blood component सँग सामान्यतया normal saline प्रयोग हुन्छ; blood bank र अस्पतालको नियम पालना गर्नुहोस्।","Transfusion"],["Which finding may indicate fluid overload during perioperative care?","Perioperative care मा fluid overload को संकेत कुन हुन सक्छ?",["New crackles, raised JVP or respiratory distress","Dry mucosa only","Low temperature alone","Isolated skin itch"],0,"Fluid overload may cause pulmonary crackles, raised venous pressure and respiratory distress.","Fluid overload मा फोक्सोमा crackles, venous pressure बढ्ने र श्वास समस्या हुन सक्छ।","Fluids"],["Which surgical wound class describes an operation entering the alimentary or respiratory tract under controlled conditions without unusual contamination?","नियन्त्रित अवस्थामा alimentary वा respiratory tract खोलिने तर असामान्य contamination नभएको wound class कुन हो?",["Clean-contaminated","Clean","Contaminated","Dirty/infected"],0,"Clean-contaminated wounds involve controlled entry into colonized tracts.","Clean-contaminated wound मा colonized tract नियन्त्रित रूपमा खोलिन्छ।","Surgery"],["Which instrument is commonly used to grasp delicate bowel tissue atraumatically?","आन्द्राको नाजुक tissue कम चोट पुर्‍याएर समात्न कुन instrument प्रयोग हुन्छ?",["Kocher forceps","Babcock forceps","Towel clip","Bone rongeur"],1,"Babcock forceps have a fenestrated, relatively atraumatic design for delicate tubular structures such as bowel.","Babcock forceps को बनावटले bowel जस्ता नाजुक संरचना कम चोट पुर्‍याएर समात्न मद्दत गर्छ।","General Surgery"],["Which instrument is designed to clamp a bleeding artery?","रक्तस्राव भइरहेको धमनी clamp गर्न कुन instrument प्रयोग गरिन्छ?",["Artery forceps","Mayo scissors","Sponge holder","Retractor"],0,"Artery forceps are haemostatic clamps used to control bleeding vessels temporarily.","Artery forceps रक्तस्राव नियन्त्रण गर्न रक्तनली अस्थायी रूपमा clamp गर्ने उपकरण हो।","General Surgery"],["Which position is commonly used for many pelvic and perineal procedures?","धेरै pelvic तथा perineal procedure मा कुन position प्रयोग गरिन्छ?",["Prone","Supine","Lithotomy","Trendelenburg only"],2,"Lithotomy provides access to the perineum and pelvic region; protect pressure points and nerves.","Lithotomy position ले perineum र pelvic क्षेत्र पहुँचयोग्य बनाउँछ; pressure point र nerve जोगाउनुपर्छ।","Gynaecology"],["A common operation to remove the uterus is called:","पाठेघर हटाउने शल्यक्रियालाई के भनिन्छ?",["Oophorectomy","Hysterectomy","Cystoscopy","Nephrectomy"],1,"Hysterectomy is surgical removal of the uterus; the extent depends on the indication and procedure.","Hysterectomy भनेको पाठेघर हटाउने शल्यक्रिया हो; कति भाग हटाउने भन्ने indication मा निर्भर हुन्छ।","Gynaecology"],["Which instrument is commonly used to hold bone during orthopaedic surgery?","Orthopaedic surgery मा हड्डी समात्न सामान्यतया कुन उपकरण प्रयोग हुन्छ?",["Bone-holding forceps","Allis tissue forceps","Mosquito forceps","Sponge-holding forceps"],0,"Bone-holding forceps provide a firm grip on bone during reduction or fixation.","Bone-holding forceps ले fracture reduction वा fixation गर्दा हड्डी मजबुत समात्छ।","Orthopaedics"],["The procedure used to examine the urinary bladder with an endoscope is:","Endoscope प्रयोग गरी urinary bladder हेर्ने procedure कुन हो?",["Bronchoscopy","Cystoscopy","Colonoscopy","Arthroscopy"],1,"Cystoscopy allows visualization of the urethra and urinary bladder using a cystoscope.","Cystoscopy मा cystoscope प्रयोग गरी urethra र urinary bladder भित्रबाट हेरिन्छ।","Urology"],["Which instrument is used to visualize the larynx during direct laryngoscopy?","Direct laryngoscopy गर्दा larynx हेर्न कुन उपकरण प्रयोग हुन्छ?",["Laryngoscope","Otoscope","Cystoscope","Gastroscope"],0,"A laryngoscope is used to visualize the larynx, commonly for airway assessment and intubation.","Laryngoscope ले larynx हेर्न मद्दत गर्छ र airway assessment तथा intubation मा प्रयोग हुन्छ।","ENT/Anaesthesia"],["A tonsillectomy is the removal of the:","Tonsillectomy मा कुन अंग हटाइन्छ?",["Thyroid gland","Tonsils","Parotid gland","Nasal septum"],1,"Tonsillectomy is surgical removal of the palatine tonsils.","Tonsillectomy भनेको palatine tonsils हटाउने शल्यक्रिया हो।","ENT"],["Which instrument is commonly used to retract the brain gently during neurosurgery?","Neurosurgery मा brain tissue लाई सावधानीपूर्वक retract गर्न कुन instrument प्रयोग हुन्छ?",["Brain spatula","Bone cutter","Towel clip","Sponge forceps"],0,"A brain spatula/retractor is used to gently protect and retract neural tissue; excessive pressure must be avoided.","Brain spatula/retractor ले neural tissue लाई सावधानीपूर्वक retract गर्छ; धेरै दबाब दिनु हुँदैन।","Neurosurgery"],["Which procedure creates an opening in the trachea to establish an airway?","Airway बनाउन trachea मा opening बनाउने procedure कुन हो?",["Thoracotomy","Tracheostomy","Laparotomy","Craniotomy"],1,"Tracheostomy creates an opening into the trachea for airway access, often by placing a tracheostomy tube.","Tracheostomy मा trachea मा opening बनाएर airway access का लागि tube राखिन्छ।","ENT/Anaesthesia"],["What is the main purpose of the water-seal chamber in an intercostal chest drain?","Intercostal chest drain मा water-seal chamber को मुख्य काम के हो?",["Allow air/fluid to leave the pleural space while preventing backflow of air","Deliver oxygen to the lung","Measure blood glucose","Sterilize the pleural cavity"],0,"The water seal acts as a one-way mechanism that allows air to escape from the pleural space and helps prevent air returning.","Water seal ले pleural space बाट हावा बाहिर जान दिन्छ र हावा फेरि भित्र पस्न नदिने one-way mechanism को काम गर्छ।","Thoracic Surgery"],["Which surgical approach uses a small incision to enter the chest cavity?","छातीको cavity मा प्रवेश गर्न सानो incision प्रयोग गर्ने surgical approach कुन हो?",["Thoracoscopy","Laparotomy","Cystoscopy","Arthroplasty"],0,"Thoracoscopy is endoscopic visualization of the thoracic cavity through small ports.","Thoracoscopy मा साना port बाट endoscope प्रयोग गरी thoracic cavity हेरिन्छ।","Thoracic Surgery"],["Which component of the anaesthesia machine prevents delivery of a hypoxic oxygen-nitrous oxide mixture?","Anaesthesia machine मा oxygen र nitrous oxide को hypoxic mixture जान नदिन कुन प्रणालीले मद्दत गर्छ?",["Oxygen failure protection and proportioning system","Waste gas scavenging only","Vapourizer filling port","Breathing bag alone"],0,"Oxygen failure protection and proportioning systems reduce the risk of delivering a dangerously low oxygen concentration; they do not replace monitoring.","Oxygen failure protection र proportioning system ले oxygen कम भएको खतरनाक mixture जानबाट जोखिम घटाउँछ; monitoring को विकल्प होइन।","Anaesthesia Machine"],["Which part of the breathing system allows manual ventilation and provides a visual indication of ventilation?","Breathing system को कुन भागले manual ventilation गर्न र ventilation देख्न मद्दत गर्छ?",["Reservoir bag","Flowmeter bobbin","Soda lime canister","Scavenging hose"],0,"The reservoir bag can be used for manual ventilation and its movement helps assess breathing-system activity.","Reservoir bag manual ventilation मा प्रयोग हुन्छ र यसको movement ले breathing-system activity बुझ्न मद्दत गर्छ।","Anaesthesia Machine"],["What is the main function of soda lime in a circle breathing system?","Circle breathing system मा soda lime को मुख्य काम के हो?",["Absorb carbon dioxide","Absorb oxygen","Deliver volatile anaesthetic","Humidify compressed air only"],0,"Soda lime absorbs exhaled carbon dioxide so that gas can be rebreathed after appropriate system checks.","Soda lime ले बिरामीले फालेको carbon dioxide सोस्छ, त्यसपछि उपयुक्त जाँचपछि gas पुनः सासमा जान सक्छ।","Anaesthesia Machine"],["Which clinical sign is a classic early clue to malignant hyperthermia during anaesthesia?","Anaesthesia क्रममा malignant hyperthermia को प्रारम्भिक महत्वपूर्ण संकेत कुन हो?",["Rapid rise in end-tidal CO₂ with unexplained tachycardia","Slow nail growth","Mild isolated rash","Low urine colour intensity"],0,"A rising ETCO₂ despite adequate ventilation and unexplained tachycardia may be early signs; hyperthermia can occur later.","पर्याप्त ventilation हुँदाहुँदै ETCO₂ बढ्नु र कारण नखुलेको tachycardia प्रारम्भिक संकेत हुन सक्छ; ज्वरो पछि आउन सक्छ।","Anaesthesia Emergencies"],["Which drug is the specific first-line treatment for malignant hyperthermia?","Malignant hyperthermia को विशिष्ट पहिलो उपचार कुन औषधि हो?",["Dantrolene","Atropine","Naloxone","Protamine"],0,"Dantrolene is the specific treatment; stop triggering agents, call for help, provide high-flow oxygen and follow the emergency protocol.","Dantrolene विशिष्ट उपचार हो; trigger औषधि रोक्ने, सहयोग बोलाउने, high-flow oxygen दिने र emergency protocol पालना गर्ने।","Anaesthesia Emergencies"],["Which electrolyte abnormality is particularly associated with massive blood transfusion because of citrate binding?","Massive blood transfusion मा citrate ले बाँध्ने भएकाले कुन electrolyte घट्न सक्छ?",["Ionized calcium","Sodium only","Chloride only","Phosphate only"],0,"Citrate in stored blood can bind ionized calcium, causing hypocalcaemia; monitor clinically and with laboratory testing.","Stored blood को citrate ले ionized calcium बाँध्न सक्छ र hypocalcaemia हुन सक्छ; clinical र laboratory monitoring गर्नुपर्छ।","Transfusion"],["Which blood component is primarily used to improve oxygen-carrying capacity in symptomatic anaemia?","लक्षणसहितको anaemia मा oxygen बोक्ने क्षमता बढाउन कुन blood component दिइन्छ?",["Packed red blood cells","Platelet concentrate","Fresh frozen plasma","Cryoprecipitate"],0,"Packed red cells increase haemoglobin and oxygen-carrying capacity when transfusion is clinically indicated.","Packed red cells ले haemoglobin र oxygen बोक्ने क्षमता बढाउँछ, आवश्यक clinical indication हुँदा प्रयोग गरिन्छ।","Transfusion"],["Which blood component is most appropriate for significant thrombocytopenia with bleeding when indicated?","रक्तस्रावसहित platelet धेरै कम भएको अवस्थामा indication भए कुन component उपयुक्त हुन्छ?",["Platelets","Packed red cells only","Albumin","Normal saline"],0,"Platelet transfusion may be indicated for clinically significant thrombocytopenia with bleeding, depending on cause and protocol.","कारण र protocol अनुसार रक्तस्रावसहित platelet कम हुँदा platelet transfusion आवश्यक हुन सक्छ।","Transfusion"],["Which observation is most important during the first 15 minutes of a blood transfusion?","Blood transfusion को सुरुको १५ मिनेटमा कुन कुरा विशेष निगरानी गर्नुपर्छ?",["Closely observe for an acute transfusion reaction","Allow the patient to leave the ward","Stop all vital-sign monitoring","Warm the blood in hot water"],0,"Acute reactions may occur early; verify identity, baseline observations and monitor closely according to local policy.","Acute reaction सुरुमा देखिन सक्छ; पहिचान, baseline observation र स्थानीय policy अनुसार नजिकबाट निगरानी गर्नुपर्छ।","Transfusion"],["Which patient position is commonly used for thyroid surgery?","Thyroid surgery मा सामान्यतया कुन position प्रयोग गरिन्छ?",["Supine with neck extension supported","Prone with arms overhead","Lithotomy","Lateral kidney position"],0,"Thyroidectomy is commonly performed supine with a shoulder support and carefully extended neck, protecting pressure points.","Thyroidectomy प्रायः supine अवस्थामा shoulder support र सावधानीपूर्वक neck extension सहित गरिन्छ; pressure point जोगाउनुपर्छ।","Patient Positioning"],["Which position is commonly used for a posterior approach to the kidney?","मिर्गौलाको posterior approach मा सामान्यतया कुन position प्रयोग गरिन्छ?",["Lateral kidney position","Lithotomy","Trendelenburg","Sitting upright"],0,"A lateral kidney position may be used for selected renal procedures; supports and pressure-point protection are essential.","केही renal procedure मा lateral kidney position प्रयोग हुन्छ; support र pressure point protection आवश्यक हुन्छ।","Patient Positioning"],["Which nerve is at risk of compression near the fibular head during lithotomy positioning?","Lithotomy position मा fibular head नजिक कुन nerve थिचिने जोखिम हुन्छ?",["Common peroneal nerve","Optic nerve","Facial nerve","Median nerve"],0,"The common peroneal nerve is vulnerable near the fibular head; avoid pressure and excessive leg positioning.","Common peroneal nerve fibular head नजिक हुन्छ; त्यहाँ दबाब र खुट्टाको अत्यधिक positioning रोक्नुपर्छ।","Patient Positioning"],["Which surgical approach uses a camera and instruments through small ports?","सानो port बाट camera र instrument छिराएर गरिने surgical approach कुन हो?",["Laparoscopy","Open laparotomy","Thoracotomy","Craniotomy"],0,"Laparoscopy uses a camera and instruments through small abdominal ports, commonly with carbon dioxide insufflation.","Laparoscopy मा पेटका साना port बाट camera र instrument हालिन्छ; प्रायः carbon dioxide insufflation गरिन्छ।","Laparoscopic Surgery"],["What is the purpose of carbon dioxide insufflation during laparoscopy?","Laparoscopy मा carbon dioxide insufflation गर्नुको उद्देश्य के हो?",["Create a working space in the abdominal cavity","Sterilize the abdominal organs","Stop all bleeding chemically","Replace anaesthesia"],0,"CO₂ creates pneumoperitoneum to provide space and visibility for laparoscopic surgery; pressure and patient effects require monitoring.","CO₂ ले pneumoperitoneum बनाएर instrument चलाउन ठाउँ र दृश्य दिन्छ; pressure र बिरामीमा पर्ने असर निगरानी गर्नुपर्छ।","Laparoscopic Surgery"],["Which complication can occur from prolonged pneumoperitoneum and increased intra-abdominal pressure?","लामो समय pneumoperitoneum र intra-abdominal pressure बढ्दा कुन complication हुन सक्छ?",["Reduced venous return and ventilation changes","Permanent increase in bone length","Improved renal perfusion in all patients","No physiological effect"],0,"Raised intra-abdominal pressure can reduce venous return, alter respiratory mechanics and affect renal perfusion.","पेटभित्र pressure बढ्दा venous return घट्न, श्वासप्रश्वासमा परिवर्तन आउन र renal perfusion प्रभावित हुन सक्छ।","Laparoscopic Surgery"],["Which instrument is commonly used to hold the edges of an abdominal incision apart?","पेटको incision का किनारा छुट्याएर राख्न कुन instrument प्रयोग गरिन्छ?",["Surgical retractor","Needle holder","Towel clip","Suction tubing"],0,"Retractors hold tissues aside to improve exposure; select and position them to minimize tissue injury.","Retractor ले tissue हटाएर surgical field देखाउँछ; tissue injury कम हुने गरी प्रयोग गर्नुपर्छ।","Surgical Instruments"],["Which instrument is designed to hold a suture needle securely?","Suture needle सुरक्षित समात्न बनाइएको instrument कुन हो?",["Needle holder","Babcock forceps","Kocher clamp","Rongeur"],0,"A needle holder, such as Mayo-Hegar, securely grasps the needle during suturing.","Mayo-Hegar जस्ता needle holder ले suturing गर्दा needle सुरक्षित समात्छ।","Surgical Instruments"],["What is the main purpose of a surgical drain?","Surgical drain को मुख्य उद्देश्य के हो?",["Remove collected fluid, blood or air from a surgical site","Deliver anaesthetic gas","Measure blood glucose","Sterilize the wound"],0,"Drains remove fluid, blood or air when clinically indicated and should be managed with aseptic technique and output documentation.","आवश्यकताअनुसार drain ले घाउबाट तरल, रगत वा हावा निकाल्छ; aseptic technique र output documentation आवश्यक हुन्छ।","Postoperative Care"],["Which finding may indicate postoperative haemorrhage?","Operation पछि haemorrhage भएको संकेत कुन हुन सक्छ?",["Increasing drain blood, tachycardia and falling blood pressure","Warm hands with stable observations only","Improved urine output","Normal pain relief"],0,"Increasing bloody drainage, tachycardia, pallor and hypotension require urgent assessment and escalation.","Drain मा रगत बढ्नु, मुटुको धड्कन बढ्नु, फिक्का हुनु र BP घट्नुमा तुरुन्त मूल्याङ्कन र escalation चाहिन्छ।","Postoperative Complications"],["Which measure helps prevent hypothermia in the operating room?","Operation theatre मा hypothermia रोक्न कुन उपायले मद्दत गर्छ?",["Use approved patient warming and monitor temperature","Expose the patient throughout surgery","Use cold irrigation routinely","Turn off all monitoring"],0,"Active warming, warmed fluids when appropriate and temperature monitoring help maintain normothermia.","Active warming, आवश्यक परे warmed fluid र तापक्रम निगरानीले सामान्य तापक्रम कायम राख्न मद्दत गर्छ।","Patient Safety"],["Which factor increases the risk of pressure injury during a long operation?","लामो operation मा pressure injury को जोखिम कुन कारणले बढ्छ?",["Prolonged pressure over bony prominences","Appropriate padding","Regular team checks","Correct alignment"],0,"Prolonged pressure and shear reduce tissue perfusion; use padding, alignment and risk-based checks.","हड्डी निस्केको भागमा लामो दबाब र shear ले रक्तप्रवाह घटाउँछ; padding, सही alignment र नियमित जाँच आवश्यक हुन्छ।","Patient Positioning"],["Which action should be taken first if a patient develops suspected anaphylaxis in the operating room?","OT मा बिरामीलाई anaphylaxis भएको शंका भए पहिलो कदम के हो?",["Call for help, stop suspected trigger and follow emergency protocol including adrenaline","Continue the procedure without assessment","Give oral fluids","Wait for a skin rash"],0,"Anaphylaxis is a life-threatening emergency; stop the trigger, call for help, support airway/breathing/circulation and administer IM/IV adrenaline according to setting protocol.","Anaphylaxis ज्यान जोखिमको emergency हो; trigger रोक्ने, सहयोग बोलाउने, airway/breathing/circulation सहयोग गर्ने र setting protocol अनुसार adrenaline दिने।","Anaesthesia Emergencies"],["Which feature best distinguishes hypovolaemic shock?","Hypovolaemic shock को प्रमुख विशेषता कुन हो?",["Reduced circulating blood volume with impaired tissue perfusion","Excess circulating volume","Isolated high blood glucose","Increased oxygen saturation in all cases"],0,"Blood or fluid loss reduces circulating volume and tissue perfusion; rapid recognition and cause-directed resuscitation are essential.","रगत वा तरल गुम्दा circulating volume र tissue perfusion घट्छ; छिटो पहिचान र कारणअनुसार resuscitation आवश्यक हुन्छ।","Shock"],["Which laboratory test is commonly used to assess the extrinsic and common coagulation pathways?","Extrinsic र common coagulation pathway जाँच्न कुन laboratory test प्रयोग हुन्छ?",["Prothrombin time (PT/INR)","Serum amylase","Blood urea","Urine ketone"],0,"PT/INR assesses the extrinsic and common pathways and is used in evaluating coagulation and warfarin effect.","PT/INR ले extrinsic र common pathway मूल्याङ्कन गर्छ र coagulation तथा warfarin प्रभाव जाँच्न प्रयोग हुन्छ।","Haemostasis"],["Which action is essential when sending a removed tissue specimen for histopathology?","निकालिएको tissue histopathology का लागि पठाउँदा कुन काम अनिवार्य हुन्छ?",["Correct patient/site labelling and appropriate container/fixative per lab policy","Place it in an unlabelled kidney dish","Send it with no request form","Mix it with another patient's specimen"],0,"Accurate patient identifiers, specimen site/laterality, correct container and request documentation prevent diagnostic errors.","सही patient identifier, specimen site/laterality, उपयुक्त container र request form ले diagnostic गल्ती रोक्छ।","Specimen Handling"],["Which hormone lowers blood glucose by promoting cellular uptake?","कोशिकामा glucose प्रवेश बढाएर रगतको glucose घटाउने hormone कुन हो?",["Glucagon","Insulin","Cortisol","Adrenaline"],1,"Insulin promotes glucose uptake and storage, lowering blood glucose.","Insulin ले glucose uptake र storage बढाएर रगतमा glucose घटाउँछ।","Biochemistry"],["Which drug reaction is an immune-mediated response to a medicine?","औषधिप्रति immune-mediated प्रतिक्रिया कुन हो?",["Hypersensitivity","Tolerance","Placebo effect","Drug accumulation"],0,"Drug hypersensitivity is an immune-mediated adverse reaction and may range from rash to anaphylaxis.","Drug hypersensitivity immune-mediated प्रतिकूल प्रतिक्रिया हो; rash देखि anaphylaxis सम्म हुन सक्छ।","Pharmacology"],["Which bacterium is a common cause of skin and surgical-site infection?","छाला र surgical-site infection गराउने सामान्य bacteria कुन हो?",["Staphylococcus aureus","Vibrio cholerae","Mycobacterium leprae","Candida albicans"],0,"Staphylococcus aureus is a frequent cause of skin and surgical-site infections.","Staphylococcus aureus छाला र surgical-site infection को सामान्य कारण हो।","Microbiology"],["Which blood-borne virus is an occupational hazard for OT personnel?","OT कर्मचारीका लागि रगतबाट सर्ने occupational hazard virus कुन हो?",["Hepatitis B virus","Rhinovirus","Rotavirus","Measles virus"],0,"Hepatitis B can spread through blood and body fluids; vaccination and standard precautions are essential.","Hepatitis B रगत र body fluid बाट सर्न सक्छ; खोप र standard precaution आवश्यक छन्।","Microbiology"],["What should be done first after a needlestick exposure?","Needlestick exposure भएपछि सबैभन्दा पहिले के गर्नुपर्छ?",["Wash, report promptly and obtain urgent risk assessment","Hide the incident","Wait several weeks","Apply bleach to the wound"],0,"Immediate first aid, prompt reporting and urgent occupational-health assessment allow timely post-exposure management.","तुरुन्त first aid, report र occupational-health मूल्याङ्कनले post-exposure management समयमै गर्न मद्दत गर्छ।","Occupational Safety"],["What should be done with a sterile package that becomes wet or torn?","Sterile package भिजेमा वा च्यातिएमा के गर्नुपर्छ?",["Treat it as compromised and reprocess","Use if label is intact","Dry it with towel and use","Use only for minor surgery"],0,"Moisture or damage compromises the sterile barrier; reprocess according to policy.","भिजेको वा च्यातिएको package को sterile barrier बिग्रन्छ; policy अनुसार पुनः processing गर्नुपर्छ।","Sterilization"],["Which three parameters are essential to validated steam sterilization?","Steam sterilization का तीन महत्वपूर्ण parameter कुन हुन्?",["Time, temperature and steam contact","Handle colour, weight and light","Room size, noise and humidity","Label, date and shelf"],0,"Validated steam sterilization depends on time, temperature and saturated steam contact.","Steam sterilization समय, तापक्रम र saturated steam को सम्पर्कमा निर्भर हुन्छ।","Sterilization"],["What does an internal chemical indicator show?","Internal chemical indicator ले के देखाउँछ?",["Whether specified sterilizing conditions reached inside the pack","Proof of sterility by itself","The patient's identity","Instrument sharpness"],0,"An internal chemical indicator helps assess conditions inside the package but does not alone prove sterility.","Internal chemical indicator ले package भित्रको condition देखाउँछ तर एक्लैले sterility प्रमाणित गर्दैन।","CSSD"],["Which action is needed if the sterile field is contaminated?","Sterile field दूषित भएमा के गर्नुपर्छ?",["Inform the team and restore the sterile barrier safely","Cover with an unsterile towel","Ignore if dry","Continue without telling anyone"],0,"Recognize and communicate contamination immediately, then correct it using sterile technique.","दूषण तुरुन्त पहिचान गरी team लाई जानकारी दिने र sterile technique बाट सुधार गर्ने।","Aseptic Technique"],["Which combination can cause an operating-room fire?","OT मा आगलागी गराउन सक्ने संयोजन कुन हो?",["Oxidizer, ignition source and fuel","Water, saline and gauze","Suction, vacuum and monitor","Cotton, sterile water and light"],0,"A surgical fire requires an oxidizer, ignition source and fuel; manage oxygen and electrosurgery carefully.","Surgical fire का लागि oxidizer, ignition source र fuel चाहिन्छ; oxygen र electrosurgery सावधानीपूर्वक व्यवस्थापन गर्नुपर्छ।","OT Safety"],["Which airway device sits above the glottis?","Glottis माथि बस्ने airway device कुन हो?",["Supraglottic airway device","Urinary catheter","Nasogastric tube","Chest drain"],0,"A supraglottic airway device sits above the glottis and can provide ventilation in selected cases.","Supraglottic airway device glottis माथि बस्छ र उपयुक्त अवस्थामा ventilation दिन्छ।","Airway Management"],["Which position is commonly used for vaginal and perineal procedures?","Vaginal र perineal procedure मा कुन position प्रयोग हुन्छ?",["Lithotomy","Prone","Sitting","Supine legs together"],0,"Lithotomy provides access to the perineum and vagina; protect nerves and avoid excessive hip positioning.","Lithotomy ले perineum र vagina सम्म पहुँच दिन्छ; nerve जोगाउने र hip अत्यधिक नतान्ने।","Gynaecology"],["Which operation removes the uterus?","Uterus हटाउने operation कुन हो?",["Hysterectomy","Oophorectomy","Cystoscopy","Colporrhaphy"],0,"Hysterectomy removes the uterus through abdominal, vaginal or laparoscopic approaches.","Hysterectomy मा abdominal, vaginal वा laparoscopic विधिबाट uterus हटाइन्छ।","Gynaecology"],["Which operation replaces a severely damaged hip joint?","धेरै बिग्रिएको hip joint प्रतिस्थापन गर्ने operation कुन हो?",["Tendon repair","Arthroscopy only","Closed reduction","Total hip arthroplasty"],3,"Total hip arthroplasty replaces damaged joint surfaces with prosthetic components.","Total hip arthroplasty मा बिग्रिएको joint सतह कृत्रिम component ले बदलिन्छ।","Orthopaedics"],["Which eye operation removes a cloudy lens and commonly inserts an intraocular lens?","धमिलो lens हटाएर intraocular lens राख्ने आँखाको operation कुन हो?",["Cataract surgery","Trabeculectomy","Vitrectomy only","Dacryocystorhinostomy"],0,"Cataract surgery removes the opacified lens and commonly implants an intraocular lens.","Cataract surgery मा धमिलो lens हटाएर सामान्यतया intraocular lens राखिन्छ।","Ophthalmology"]];const topics=[["1. Anatomy & Physiology (10%)","Anatomical terms, body organization, cells, tissues and body regions; overview of GIT, respiratory, excretory, genital, endocrine, special senses, nervous, lymphatic and skeletal systems. Physiology of muscular, nervous, cardiovascular, respiratory, digestive, excretory, endocrine and reproductive systems.","शरीरका anatomical terms, cell/tissue, अंग र प्रणालीको आधारभूत बनावट तथा मांसपेशी, स्नायु, मुटु–रक्तसञ्चार, श्वासप्रश्वास, पाचन, उत्सर्जन, endocrine र प्रजनन प्रणालीको कार्य पढ्नुहोस्।"],["2. Biochemistry (part of 15%)","Biochemistry and scope; electrolytes; carbohydrate digestion and absorption; blood glucose regulation; urea and creatinine formation; tests for sugar, urea, creatinine and protein in blood/urine; renal function tests; urine physical and chemical characteristics; blood pH regulation.","Electrolytes, carbohydrate digestion, glucose control, urea/creatinine, blood तथा urine test, renal function test, urine analysis र acid–base balance बुझ्नुहोस्।"],["3. Pharmacology (part of 15%)","Materia medica, drug standards and laws, dosage, minimum/maximum/toxic/lethal doses, idiosyncrasy, hypersensitivity, local/systemic action and routes. Common analgesics, antiseptics, disinfectants, antibiotics, tranquilizers, sulfonamides and local/general anaesthetics.","औषधिको मात्रा, route, local/systemic action, allergy/hypersensitivity, toxicity, analgesics, antiseptics, disinfectants, antibiotics र local/general anaesthetic को आधारभूत ज्ञान पढ्नुहोस्।"],["4. Microbiology (part of 15%)","Sterilization and disinfection; bacterial classification, morphology and reproduction; immunity; Staphylococcus, Streptococcus, diphtheria, Clostridium tetani/perfringens, anthrax, Mycobacterium tuberculosis/leprosy, E. coli, Salmonella, Shigella, Vibrio, Pseudomonas; Candida, Cryptococcus; hepatitis, HIV, herpes; nosocomial infection, universal precautions and waste disposal.","Sterilization, disinfection, bacteria/virus/fungi, immunity, सूचीमा भएका रोगजनक, hospital-acquired infection, universal precautions र biomedical waste management अध्ययन गर्नुहोस्।"],["5. OT Fundamentals & Teamwork (40%)","Modern surgery and OT roles; learning objectives and standardized procedures; healthcare team, sterile/unst erile team members, direct patient care, administrative and support staff; teamwork and communication.","OT को भूमिका, scrub/circulating team, sterile तथा non-sterile सदस्य, teamwork, communication र standardized procedure बुझ्नुहोस्।"],["6. Patient-centred & Pre-operative Nursing","Patient needs and response to illness; physician-patient relationship; acceptance of operation; special needs; preoperative assessment, planning, implementation and evaluation; patient identification, checklist and preparation.","बिरामीको आवश्यकता, डर/प्रतिक्रिया, विशेष आवश्यकता, preoperative history, assessment, planning, checklist, consent र patient identification पढ्नुहोस्।"],["7. OT Physical Facilities, Asepsis & CSSD","OT layout, exchange and peripheral support areas; contamination sources; surgical conscience; sterile technique principles; infection prevention; bioburden; sterilization parameters and monitoring; disinfection; CSSD.","OT layout, asepsis, sterile field, contamination, infection prevention, sterilization monitoring र Central Sterile Supply Department (CSSD) पढ्नुहोस्।"],["8. Scrub, Gowning, Gloving, Counts & Cleaning","Surgical hand scrub/hand antisepsis; sterile gown and gloves; scrub and circulating duties; sponge, sharp and instrument counts; setup; daily, weekly and monthly OT cleaning; waste segregation.","Surgical hand antisepsis, gown/glove लगाउने तरिका, sponge/sharp/instrument count, OT setup, सफाइ र waste segregation पढ्नुहोस्।"],["9. Safety, Equipment & Specimens","Time/motion and supply economy; disposable vs reusable equipment; instrument care; electrical and radiation hazards; medical gas, vacuum suction and scavenging; cautery and harmonic scalpel; specimen handling for histopathology and microbiology.","उपकरणको सुरक्षित प्रयोग, electrical/radiation hazard, gas pipeline, suction, scavenging, cautery, harmonic scalpel र specimen labelling/transport बुझ्नुहोस्।"],["10. Anaesthesia & Allied Topics","Pain, premedication, choice and stages of anaesthesia; general, local, regional, spinal and epidural techniques; neuromuscular blockers; balanced anaesthesia; anaesthetized patient care; neonatal/elderly considerations; equipment and occupational hazards; complications.","Anaesthesia का प्रकार, premedication, airway, anaesthesia equipment, muscle relaxants, बिरामीको निगरानी, विशेष उमेर समूह र complication पढ्नुहोस्।"],["11. Anaesthesia Drugs, CPR, Fluids & Blood","Anaesthetic drugs; narcotic/non-narcotic analgesics; steroids, bronchodilators, antihistamines, vasopressors, vasodilators, cardiomimetics and antiarrhythmics; CPR; venous access, cannulae, administration sets, crystalloids/colloids; blood groups, crossmatch, storage, incompatibility and transfusion reactions.","Anaesthesia तथा emergency औषधि, CPR, IV access, fluids, blood group/crossmatch, transfusion र transfusion reaction को आधारभूत ज्ञान पढ्नुहोस्।"],["12. Medico-legal, Accountability & Patient Safety","Medico-legal aspects, liability, accountability, patient and employee safety programmes, stress, clinical competence and professional conduct.","Consent, documentation, confidentiality, liability, accountability, patient safety र कर्मचारी सुरक्षा बुझ्नुहोस्।"],["13. Ambulatory, Monitoring, Positioning & Draping (35%)","Ambulatory surgery and recovery/discharge; patient reception and checklist; vital-function monitoring and complications; supine, prone, lateral, lithotomy and other operative positions; pressure/nerve injury risks; operative-site preparation, NG intubation, urinary catheterization and draping.","Day surgery, recovery, vital monitoring, operative positions, nerve/pressure injury, skin preparation, NG tube, urinary catheter र draping पढ्नुहोस्।"],["14. Wounds, Haemostasis & Closure","Wound healing and influencing factors; haemostasis methods; sutures, needles, suturing techniques, staples, tissue adhesives, repair/replacement materials and skin closure.","Wound healing का चरण, haemostasis, suture/needle प्रकार, suturing, staples र tissue adhesive बुझ्नुहोस्।"],["15. State-of-the-art & Diagnostic Procedures","Electrosurgery, laser surgery, endoscopy, microsurgery; radiology, ultrasonography, endoscopy, plethysmography and evoked potentials; laparoscopic surgery and instruments.","Electrosurgery, laser, endoscopy, microsurgery, imaging/diagnostic procedures र laparoscopy का उपकरण/सिद्धान्त पढ्नुहोस्।"],["16. Operative Procedures by Specialty","General surgery (neck, breast, abdominal, biliary, liver, spleen, pancreas, oesophagus, stomach, intestine, colorectal/anorectal, hernia, amputation); Gynaecology/obstetrics; Orthopaedics; Ophthalmology; ENT; plastic/reconstructive and burns; paediatric; cardiac and vascular; thoracic; urology; transplantation; oncology; neurosurgery; head and neck.","General surgery, Gynae/Obs, Orthopaedics, Eye, ENT, Plastic, Paediatric, Cardiac, Vascular, Thoracic, Urology, Transplant, Oncology, Neurosurgery र Head & Neck का common operation तथा OT तयारी पढ्नुहोस्।"],["17. Complications & Laparoscopy","Pulmonary and cardiovascular complications, shock, haemorrhage, DIC, wound infection/dehiscence, abdominal and renal complications, electrolyte imbalance; laparoscopic equipment and procedures.","Postoperative pulmonary/CVS complication, shock, bleeding, DIC, wound infection/dehiscence, renal/electrolyte समस्या र laparoscopic procedures अध्ययन गर्नुहोस्।"],["18. Practical Skills","Instrument washing and ultrasonic bath; identify instruments for surgeries; identify anaesthesia equipment; handle sophisticated anaesthetic/surgical equipment; OT waste disposal; position patients; handle sterile materials; sterilize laparoscopic/endoscopic instruments.","Instrument washing, ultrasonic bath, instrument identification, anaesthesia equipment, waste disposal, patient positioning, sterile material handling र laparoscopic/endoscopic instrument sterilization अभ्यास गर्नुहोस्।"]];const detailedNotes=[["CSSD & Sterilization","Reusable instruments move through receiving, sorting, cleaning, inspection, packaging, sterilization, storage and distribution. Cleaning comes first because organic soil can protect microbes. Steam sterilization requires a validated cycle and monitoring by physical records, chemical indicators and biological indicators as required. A failed cycle must not be released.","Reusable instrument receiving, sorting, cleaning, inspection, packaging, sterilization, storage र distribution चरणबाट जान्छ। मैलोले microorganism छोप्ने भएकाले cleaning पहिले हुन्छ। Steam sterilization मा validated cycle र physical, chemical तथा आवश्यक biological indicator बाट monitoring चाहिन्छ। Fail भएको load प्रयोग गर्नु हुँदैन।"],["Asepsis & Sterile Field","Sterile items touch only sterile items. If sterility is uncertain, consider the item contaminated. Keep the sterile field visible and above waist level. Moisture can cause strike-through contamination. Avoid reaching over the sterile field. Surgical conscience means following aseptic principles consistently.","Sterile सामानले sterile सामानलाई मात्र छुनुपर्छ। शंका भए contaminated मान्ने। Sterile field आँखाको अगाडि र कम्मरभन्दा माथि राख्ने। भिजेको कपडाबाट microorganism पार हुन सक्छ। Sterile field माथिबाट हात नलैजाने। Surgical conscience भनेको सधैँ aseptic नियम पालना गर्नु हो।"],["Scrub, Gowning & Gloving","Remove jewellery and keep nails short. Perform surgical hand antisepsis according to product instructions. Dry with a sterile towel and don the gown without contaminating its outside. Closed gloving is commonly used after gowning. Replace torn or contaminated gloves immediately.","गहना हटाउने र नङ छोटो राख्ने। Product निर्देशनअनुसार surgical hand antisepsis गर्ने। Sterile towel ले सुकाएर gown को बाहिरी भाग नछुने गरी gown लगाउने। Gown पछि closed gloving सामान्य हो। पञ्जा च्यातिए वा दूषित भए तुरुन्त बदल्ने।"],["Anaesthesia & Monitoring","General anaesthesia causes controlled unconsciousness and may require airway support. Local anaesthesia numbs a limited area; regional techniques include spinal and epidural. Monitor oxygenation, ventilation, circulation and temperature. Common monitors include pulse oximetry, ECG, blood pressure and capnography when indicated. Assess the patient, not just the monitor.","General anaesthesia ले बिरामीलाई नियन्त्रित रूपमा अचेत बनाउँछ र airway support चाहिन सक्छ। Local ले सीमित भाग सुन्न बनाउँछ; regional मा spinal र epidural पर्छन्। Oxygenation, ventilation, circulation र temperature monitor गर्ने। Pulse oximetry, ECG, BP र आवश्यकताअनुसार capnography प्रयोग हुन्छ। Monitor मात्र होइन, बिरामी पनि हेर्नुपर्छ।"],["CPR & Emergency","Recognize unresponsiveness and absent/abnormal breathing, call for help and start high-quality CPR. Adult compression rate is 100–120/min and depth about 5–6 cm, with full recoil and minimal pauses. Attach AED promptly. VF and pulseless VT are shockable; asystole and PEA are not.","बिरामी प्रतिक्रिया नदिने र सामान्य सास नफेर्ने भए सहयोग बोलाएर CPR सुरु गर्ने। वयस्कमा 100–120 compression/min र करिब 5–6 cm गहिराइ, पूर्ण recoil र कम pause राख्ने। AED छिटो जोड्ने। VF र pulseless VT shockable हुन्; asystole र PEA होइनन्।"],["Blood Transfusion Safety","Before transfusion verify the prescription, patient identity, component, compatibility and expiry. If a reaction is suspected, stop transfusion immediately, maintain IV access according to policy, assess the patient and notify the responsible clinician and blood bank. Do not restart unless directed after assessment.","Transfusion अघि prescription, बिरामीको पहिचान, blood component, compatibility र expiry जाँच्ने। Reaction शंका भए तुरुन्त transfusion रोक्ने, policy अनुसार IV access कायम गर्ने, बिरामी जाँच्ने र clinician तथा blood bank लाई खबर गर्ने। मूल्याङ्कनपछि निर्देशन नआएसम्म पुनः सुरु नगर्ने।"],["Positioning & Pressure Injury","Choose supine, prone, lateral or lithotomy according to the procedure and patient. Protect eyes, airway, pressure points and peripheral nerves. Use padding and secure the patient without impairing breathing or circulation. Recheck alignment after table movement.","Procedure र बिरामीअनुसार supine, prone, lateral वा lithotomy छान्ने। आँखा, airway, pressure points र nerve जोगाउने। Padding राखी सास र circulation नरोकिने गरी बिरामी सुरक्षित गर्ने। Table चलाएपछि alignment फेरि जाँच्ने।"],["Specimen Handling","Confirm specimen identity and site with the surgeon. Label immediately with patient identifiers, anatomical site, specimen type, date/time and requested test. Use the correct container and preservative; some microbiology samples must not be placed in formalin. Transport promptly using facility procedure.","Specimen को पहिचान र site surgeon सँग पुष्टि गर्ने। Patient identifier, anatomical site, specimen type, मिति/समय र test लेखेर तुरुन्त label गर्ने। सही container र preservative प्रयोग गर्ने; केही microbiology sample formalin मा राख्नु हुँदैन। संस्थाको प्रक्रियाअनुसार छिटो पठाउने।"],["Recovery & Postoperative Complications","In recovery assess airway, breathing, circulation, consciousness, pain, temperature, wound and urine output. Watch for hypoxia, haemorrhage, shock, arrhythmia, aspiration, pulmonary embolism, hypothermia, infection and wound dehiscence. Escalate deteriorating vital signs or respiratory distress and follow formal discharge criteria.","Recovery मा airway, सास, circulation, चेतना, दुखाइ, तापक्रम, घाउ र urine output हेर्ने। Hypoxia, bleeding, shock, arrhythmia, aspiration, pulmonary embolism, hypothermia, infection र wound dehiscence हेर्ने। Vital signs बिग्रिए वा सास गाह्रो भए तुरुन्त खबर गर्ने र discharge criteria पालना गर्ने।"],["Surgical Instrument Identification","Identify instruments by function: cutting (scalpel, scissors), grasping (forceps), clamping (haemostats), retracting (retractors), suturing (needle holders) and suction (cannula). Check the tip, handle, ratchet and joints. Inspect for damage and correct function before use.","Instrument लाई कामअनुसार cutting (scalpel, scissors), grasping (forceps), clamping (haemostat), retracting, suturing (needle holder) र suction (cannula) मा छुट्याइन्छ। Tip, handle, ratchet र joint हेरेर पहिचान गर्ने। प्रयोगअघि क्षति र काम गर्ने अवस्था जाँच्ने।"],["Forceps: Allis, Babcock and Toothed","Allis forceps hold tissue firmly and can cause trauma. Babcock forceps are more atraumatic and are used for delicate tubular structures. Toothed dissecting forceps grip skin or tougher tissue. Sponge-holding forceps hold gauze or swabs. Choose according to tissue and procedure.","Allis forceps ले tissue बलियो समात्छ तर चोट लाग्न सक्छ। Babcock तुलनात्मक रूपमा atraumatic हुन्छ र नाजुक tubular structure मा प्रयोग हुन्छ। Toothed forceps छाला/कडा tissue का लागि हो। Sponge-holding forceps ले gauze समात्छ। Tissue अनुसार छान्ने।"],["Scissors and Cutting Instruments","Mayo scissors are sturdy and may be used for heavier tissue or sutures. Metzenbaum scissors are designed for delicate tissue. Iris scissors are fine scissors for delicate work. A scalpel makes an incision. Never use a delicate instrument for a task that may damage it; account for blades and sharps.","Mayo scissors बाक्लो tissue वा suture का लागि बलियो हुन्छ। Metzenbaum नाजुक tissue का लागि हो। Iris scissors सूक्ष्म काममा प्रयोग हुन्छ। Scalpel ले incision बनाउँछ। नाजुक उपकरणलाई क्षति हुने काममा प्रयोग नगर्ने र blade/sharp count गर्ने।"],["Laparoscopy Equipment","A laparoscopic setup may include a camera, monitor, light source, telescope, insufflator, CO2 supply, trocars, long instruments and suction-irrigation. Check image, light, connections, gas supply and equipment function before use. CO2 is commonly used to create pneumoperitoneum. Monitor pressure and patient status with the anaesthesia team.","Laparoscopy setup मा camera, monitor, light source, telescope, insufflator, CO2, trocar, लामो instrument र suction-irrigation हुन सक्छ। प्रयोगअघि image, light, connection, gas supply र उपकरण जाँच्ने। Pneumoperitoneum बनाउन CO2 प्रयोग हुन्छ। Anaesthesia टोलीसँग pressure र बिरामीको अवस्था monitor गर्ने।"],["Wound Healing and Sutures","Wound healing progresses through haemostasis, inflammation, proliferation and remodelling. Infection, poor perfusion, malnutrition, diabetes, smoking and excessive tension can delay healing. Sutures may be absorbable or non-absorbable. Select material according to tissue, expected healing time and procedure. Observe for redness, warmth, pus, fever and wound separation.","Wound healing मा haemostasis, inflammation, proliferation र remodelling चरण हुन्छन्। Infection, रगत कम पुग्नु, कुपोषण, diabetes, धूम्रपान र धेरै tension ले healing ढिलो गर्छ। Suture absorbable वा non-absorbable हुन्छ। Tissue र healing समयअनुसार छान्ने। रातोपन, तातोपन, पीप, ज्वरो र घाउ छुट्टिनु हेर्ने।"],["Drains and Postoperative Care","Drains remove fluid or air from selected wounds/cavities. Secure the drain, maintain the prescribed system, measure and document output, and report sudden changes. Use aseptic technique for dressing changes. In recovery, assess airway, breathing, circulation, consciousness, pain, wound and urine output.","Drain ले केही घाउ/cavity बाट तरल वा हावा निकाल्छ। Drain सुरक्षित राख्ने, prescribed system कायम गर्ने, output नापेर लेख्ने र अचानक परिवर्तन भए खबर गर्ने। Dressing change गर्दा aseptic technique प्रयोग गर्ने। Recovery मा airway, सास, circulation, चेतना, दुखाइ, घाउ र urine output जाँच्ने।"],["Transfusion Reaction Response","Stop a suspected transfusion reaction immediately, assess ABC and vital signs, maintain IV access with new tubing and compatible fluid as directed, and notify the clinician and blood bank. Recheck patient/unit identity, preserve the bag and tubing, and send samples as required. Haemolytic, febrile, allergic, septic, TRALI and TACO reactions need specific assessment; do not restart the implicated unit without explicit clinical direction.","Transfusion reaction शंका भए तुरुन्त transfusion रोक्ने, ABC र vital signs जाँच्ने, नयाँ tubing बाट protocol अनुसार IV access कायम गर्ने र clinician/blood bank लाई खबर गर्ने। बिरामी र unit को पहिचान जाँच्ने, bag/tubing सुरक्षित राख्ने र आवश्यक sample पठाउने। Haemolytic, febrile, allergic, septic, TRALI र TACO reaction छुट्टाछुट्टै मूल्याङ्कन चाहिन्छ।"],["Airway Emergencies in OT","Prepare suction, oxygen, bag-mask, airway adjuncts, laryngoscope, suitable tubes and a rescue plan before induction. Confirm tracheal tube placement with sustained waveform capnography plus clinical assessment. Laryngospasm or bronchospasm can rapidly impair ventilation; call for skilled help, support oxygenation and follow the anaesthesia emergency protocol.","Induction अघि suction, oxygen, bag-mask, airway adjunct, laryngoscope, tube र rescue plan तयार गर्नुहोस्। Tube सही ठाउँमा छ भन्ने कुरा waveform capnography र clinical assessment बाट पुष्टि गर्नुहोस्। Laryngospasm वा bronchospasm ले ventilation छिटो बिगार्न सक्छ; दक्ष सहयोग बोलाएर oxygenation support र emergency protocol पालना गर्नुहोस्।"],["Malignant Hyperthermia, Anaphylaxis & LAST","Malignant hyperthermia may present with rising ETCO2, tachycardia and rigidity; stop triggering agents, call for help, give dantrolene and activate the MH protocol. Anaphylaxis may cause sudden hypotension, bronchospasm and swelling; adrenaline is first-line with ABC support. Local anaesthetic systemic toxicity may begin with circumoral numbness, tinnitus, altered consciousness or seizure; stop injection and follow the LAST/lipid-emulsion protocol.","Malignant hyperthermia मा ETCO2 बढ्ने, tachycardia र rigidity हुन सक्छ; trigger रोक्ने, सहयोग बोलाउने, dantrolene दिने र protocol चलाउने। Anaphylaxis मा hypotension, bronchospasm र सुन्निने हुन सक्छ; ABC support सहित adrenaline पहिलो प्राथमिकता हो। LAST मा मुख वरिपरि झमझम, कान बज्ने, चेतना परिवर्तन वा seizure हुन सक्छ; injection रोक्दै LAST/lipid-emulsion protocol पालना गर्नुहोस्।"],["CSSD Load Release & Traceability","Separate dirty, clean and sterile zones and move instruments in one direction. Clean, inspect, assemble, package and label sets for traceability. Select a validated cycle compatible with the device/load. Review physical records and required chemical/biological indicators before release. Quarantine failed or questionable loads, investigate, document corrective action and recall items when indicated.","Dirty, clean र sterile zone छुट्याई instrument एक दिशामा सार्नुहोस्। सफा, निरीक्षण, set, packaging र traceable label गर्नुहोस्। Device/load अनुसार validated cycle छान्नुहोस्। Release अघि physical record र आवश्यक chemical/biological indicator जाँच्नुहोस्। Fail वा शंका भएको load quarantine गरी कारण खोज्ने, corrective action लेख्ने र आवश्यक परे recall गर्नुहोस्।"],["PACU Handover & Discharge","Transfer with a structured handover covering procedure, anaesthesia, airway, medicines, allergies, fluids, blood loss, drains, lines and concerns. In PACU assess ABC, consciousness, temperature, pain, nausea, wound and drain output. Escalate obstruction, hypoxia, bleeding or instability promptly. Discharge only after approved recovery criteria are met and documented.","Procedure, anaesthesia, airway, औषधि, allergy, fluid, blood loss, drain र समस्यासहित structured handover दिनुहोस्। PACU मा ABC, चेतना, तापक्रम, दुखाइ, वाकवाकी, घाउ र drain output जाँच्नुहोस्। Obstruction, hypoxia, bleeding वा अस्थिरता तुरुन्त escalate गर्नुहोस्। स्वीकृत recovery criteria पूरा र document भएपछि मात्र discharge गर्नुहोस्।"],["General Surgery Instrument Set","A basic general surgery tray may include scalpel handles and blades, artery forceps, dissecting forceps, scissors, needle holders, retractors, sponge holders and suction. Select instruments according to the planned procedure. Check function, cleanliness, integrity and sterility before use. Keep sharps controlled and count instruments according to local policy.","General surgery tray मा scalpel handle/blade, artery forceps, dissecting forceps, scissors, needle holder, retractor, sponge holder र suction हुन सक्छन्। Procedure अनुसार instrument छान्ने। प्रयोगअघि सफाइ, अवस्था, काम गर्ने क्षमता र sterility जाँच्ने। Sharp सामान सुरक्षित राख्ने र protocol अनुसार count गर्ने।"],["Gynaecology & Obstetric OT Preparation","Common procedures include caesarean section, dilatation and curettage, hysterectomy and ovarian procedures. Prepare positioning aids, suction, electrosurgery, instrument sets and specimen containers. Confirm patient identity, procedure, consent, allergies, blood availability when indicated and neonatal support arrangements for obstetric cases.","सामान्य procedure मा caesarean section, dilatation and curettage, hysterectomy र ovarian surgery पर्छन्। आवश्यक position aid, suction, electrosurgery, instrument set र specimen container तयार गर्ने। बिरामीको पहिचान, procedure, consent, allergy, आवश्यक परे blood availability र obstetric case मा neonatal support पुष्टि गर्ने।"],["Orthopaedic OT & Implant Safety","Orthopaedic procedures may require drills, saws, reamers, bone-holding forceps, retractors, power tools and implants. Confirm implant type and size, compatible instruments, sterility and traceability. Check power equipment and protect the patient from pressure, positioning and electrical hazards.","Orthopaedic procedure मा drill, saw, reamer, bone-holding forceps, retractor, power tool र implant चाहिन सक्छन्। Implant को प्रकार/size, मिल्ने instrument, sterility र traceability पुष्टि गर्ने। Power equipment जाँच्ने र pressure, positioning तथा electrical hazard बाट बिरामीलाई जोगाउने।"],["Urology & Endoscopic Procedures","Urological procedures may include cystoscopy, ureteroscopy, TURP and nephrectomy. Endoscopic equipment requires correct light source, camera, irrigation and outflow arrangements. Confirm the scope is intact, connections secure and irrigation fluid appropriate. Handle scopes carefully and follow validated reprocessing instructions.","Urology मा cystoscopy, ureteroscopy, TURP र nephrectomy पर्न सक्छन्। Endoscopic equipment का लागि light source, camera, irrigation र outflow व्यवस्था मिलाउने। Scope ठीक छ कि छैन, connection सुरक्षित छ कि छैन र irrigation fluid उपयुक्त छ कि छैन जाँच्ने। Scope सावधानीपूर्वक सम्हाल्ने र प्रमाणित reprocessing निर्देशन पालना गर्ने।"],["ENT & Neurosurgery Preparation","ENT cases may require head and neck positioning, microscope or endoscope, fine instruments and suction. Neurosurgery requires careful positioning, head fixation when indicated, microscope, fine bipolar cautery and delicate retractors. Prevent pressure injury, protect eyes and confirm equipment function before incision.","ENT case मा head/neck positioning, microscope वा endoscope, fine instrument र suction चाहिन सक्छ। Neurosurgery मा आवश्यकताअनुसार head fixation, microscope, fine bipolar cautery र delicate retractor चाहिन्छ। Pressure injury रोक्ने, आँखाको सुरक्षा गर्ने र incision अघि equipment जाँच्ने।"],["Thoracic Surgery & Chest Drain Care","Thoracic procedures may use thoracoscopy or thoracotomy. Chest drains remove air or fluid from the pleural space. Keep the drainage system below chest level, maintain prescribed connections, avoid kinks and document output. Report sudden large output, fresh bleeding, respiratory distress or disconnection promptly.","Thoracic surgery thoracoscopy वा thoracotomy बाट हुन सक्छ। Chest drain ले pleural space बाट हावा वा तरल निकाल्छ। Drainage system छातीभन्दा तल राख्ने, connection कायम गर्ने, tube नबटारिने बनाउने र output लेख्ने। अचानक धेरै output, ताजा रगत, सास फेर्न गाह्रो वा connection छुटेमा तुरुन्त खबर गर्ने।"],["Anaesthesia Induction, Maintenance & Recovery","General anaesthesia commonly involves induction, maintenance and emergence/recovery. Drugs and airway plans are individualized. Continuously assess oxygenation, ventilation, circulation, temperature, depth of anaesthesia and neuromuscular function when relevant. Transfer to recovery with a structured handover, including procedure, airway, drugs, fluids, blood loss, allergies and concerns.","General anaesthesia मा induction, maintenance र emergence/recovery चरण हुन्छन्। औषधि र airway योजना बिरामीअनुसार बनाइन्छ। Oxygenation, ventilation, circulation, temperature, anaesthesia depth र आवश्यकताअनुसार neuromuscular function निरन्तर मूल्याङ्कन गर्ने। Recovery मा procedure, airway, औषधि, fluid, blood loss, allergy र समस्या समेटिएको structured handover दिने।"],["Common Anaesthesia Drugs & Reversal Agents","Propofol is an induction agent; ketamine provides dissociative anaesthesia and analgesia; volatile agents may maintain anaesthesia. Succinylcholine is a depolarizing neuromuscular blocker; non-depolarizing blockers include rocuronium and vecuronium. Reversal choices depend on the drug and situation. Naloxone reverses opioid effects; flumazenil reverses benzodiazepine effects. These medicines require trained clinicians and monitoring.","Propofol induction agent हो; ketamine ले dissociative anaesthesia र analgesia दिन्छ; volatile agent ले anaesthesia कायम राख्न सक्छ। Succinylcholine depolarizing neuromuscular blocker हो; rocuronium र vecuronium non-depolarizing हुन्। Reversal औषधि प्रयोग भएको drug र अवस्थाअनुसार हुन्छ। Naloxone ले opioid र flumazenil ले benzodiazepine को प्रभाव उल्ट्याउँछ। यी औषधि प्रशिक्षित clinician र monitoring अन्तर्गत मात्र प्रयोग हुन्छन्।"],["Airway Equipment & Difficult Airway Readiness","Prepare appropriately sized face masks, oropharyngeal/nasopharyngeal airways, laryngoscope, endotracheal tubes, stylet, supraglottic airway, suction and bag-mask device. Check oxygen supply, connections and backup equipment. Confirm a rescue plan before induction. After intubation, confirm placement clinically and with waveform capnography when available, then secure the tube.","उपयुक्त size का face mask, oropharyngeal/nasopharyngeal airway, laryngoscope, endotracheal tube, stylet, supraglottic airway, suction र bag-mask device तयार गर्ने। Oxygen supply, connection र backup उपकरण जाँच्ने। Induction अघि rescue plan पुष्टि गर्ने। Intubation पछि clinical assessment र उपलब्ध भए waveform capnography बाट tube placement पुष्टि गरी सुरक्षित गर्ने।"],["Adult CPR & Defibrillation Basics","For suspected cardiac arrest, activate the emergency response, start high-quality CPR and obtain an AED/defibrillator. Adult compressions should generally be 100–120/min, 5–6 cm deep, allowing full recoil and minimizing interruptions. Follow the device prompts and current local resuscitation protocol. Team roles, timing and documentation matter.","Cardiac arrest शंका भए emergency response सक्रिय गर्ने, high-quality CPR सुरु गर्ने र AED/defibrillator ल्याउने। Adult compression सामान्यतया 100–120/min, 5–6 cm गहिरो, पूर्ण recoil सहित र interruption कम गरेर गर्ने। Device को निर्देशन र हालको स्थानीय resuscitation protocol पालना गर्ने। Team role, समय र documentation महत्त्वपूर्ण हुन्छ।"],["Blood Grouping, Crossmatching & Transfusion","ABO and Rh(D) typing, antibody screening and compatibility testing reduce transfusion risk. Check patient identity and blood component details at the bedside according to policy. Monitor baseline observations and the patient closely during transfusion. If a reaction is suspected, stop transfusion immediately, keep IV access with normal saline using new tubing as directed, assess and report; send samples and the bag/tubing as instructed.","ABO र Rh(D) typing, antibody screening तथा compatibility test ले transfusion risk घटाउँछ। Bedside मा policy अनुसार बिरामीको पहिचान र blood component विवरण जाँच्ने। Transfusion अघि baseline observation लिएर transfusion समयमा नजिकबाट निगरानी गर्ने। Reaction शंका भए तुरुन्त transfusion रोक्ने, निर्देशनअनुसार नयाँ tubing बाट normal saline ले IV access कायम गर्ने, मूल्याङ्कन र report गर्ने; निर्देशनअनुसार sample र bag/tubing पठाउने।"],["IV Fluids, Blood Components & Fluid Balance","Crystalloids include normal saline and balanced solutions; colloids include albumin and selected synthetic products. Blood components include red cells, platelets and plasma, each for specific indications. Monitor input/output, vital signs, signs of overload and response to treatment. Fluid and blood decisions require clinical assessment, prescription and local transfusion policy.","Crystalloid मा normal saline र balanced solution पर्छन्; colloid मा albumin र केही synthetic product पर्छन्। Blood component मा red cells, platelets र plasma हुन्छन्, प्रत्येकको छुट्टै indication हुन्छ। Input/output, vital signs, fluid overload का लक्षण र उपचारको response निगरानी गर्ने। Fluid तथा blood सम्बन्धी निर्णय clinical assessment, prescription र स्थानीय transfusion policy अनुसार हुन्छ।"],["Difficult Airway Preparation & Rescue","Before induction, review airway history, mouth opening, neck movement, dentition, aspiration risk and available equipment. Prepare suction, oxygen, masks, airway adjuncts, laryngoscope/video-laryngoscope, tracheal tubes, supraglottic devices and a rescue plan. Call for experienced help early when difficulty is anticipated. If ventilation or intubation fails, follow the institution's difficult-airway algorithm; prioritize oxygenation and avoid repeated traumatic attempts.","Induction अघि airway history, मुख खोल्ने क्षमता, घाँटीको movement, दाँत, aspiration risk र उपलब्ध उपकरण जाँच्ने। Suction, oxygen, mask, airway adjunct, laryngoscope/video-laryngoscope, tracheal tube, supraglottic device र rescue plan तयार राख्ने। कठिन airway को सम्भावना भए अनुभवी सहयोग छिट्टै बोलाउने। Ventilation वा intubation असफल भए संस्थाको difficult-airway algorithm पालना गर्ने; oxygenation प्राथमिकता दिने र पटकपटक चोट लाग्ने प्रयास नगर्ने।"],["Anaesthesia Machine: Pre-use Check","A machine check should follow the manufacturer checklist and local policy before each case. Confirm pipeline and cylinder supplies, pressure gauges, oxygen analyser and alarms, flow controls, vapourizer seating/fill, breathing circuit integrity, reservoir bag, carbon dioxide absorber, ventilator function, scavenging and suction. Perform the specified leak and function tests. Remove faulty equipment from service and report it; never rely on a previous user's check.","हरेक case अघि manufacturer checklist र hospital policy अनुसार machine जाँच्ने। Pipeline/cylinder supply, pressure gauge, oxygen analyser/alarm, flow control, vapourizer, breathing circuit, reservoir bag, CO₂ absorber, ventilator, scavenging र suction जाँच्ने। तोकिएको leak तथा function test गर्ने। खराब उपकरण प्रयोगबाट हटाएर report गर्ने; अघिल्लो व्यक्तिले जाँचेको भर नपर्ने।"],["Blood Transfusion: Compatibility & Reaction","Verify the patient using approved identifiers and independently check the blood component, compatibility label, expiry and prescription at the bedside according to policy. Record baseline observations and monitor closely, especially at the start. If a reaction is suspected, stop the transfusion, maintain IV access with normal saline using new tubing as directed, assess ABC and vital signs, notify the responsible clinician and blood bank, and send required samples and the component bag/tubing according to protocol. Do not restart unless specifically authorized.","Policy अनुसार bedside मा approved identifier बाट बिरामी पहिचान गरी blood component, compatibility label, expiry र prescription जाँच्ने। Baseline observation लेख्ने र सुरुमा विशेष निगरानी गर्ने। Reaction शंका भए transfusion रोक्ने, निर्देशनअनुसार नयाँ tubing बाट normal saline ले IV access कायम गर्ने, ABC र vital signs जाँच्ने, clinician र blood bank लाई खबर गर्ने तथा protocol अनुसार sample र bag/tubing पठाउने। स्पष्ट अनुमति बिना पुनः सुरु नगर्ने।"],["Surgical Positioning & Pressure Injury Prevention","Positioning is a shared team responsibility. Maintain anatomical alignment, protect eyes and airway, avoid excessive joint extension or nerve stretch, pad bony prominences and check that lines and tubes are not trapped. Consider the procedure, duration, patient condition and positioning-related risks. Reassess after table tilt or major movement and document positioning devices and skin checks according to policy.","Positioning team को साझा जिम्मेवारी हो। शरीरको alignment मिलाउने, आँखा र airway जोगाउने, joint धेरै तन्काउन वा nerve तानिन नदिने, हड्डी निस्केका भागमा padding राख्ने र line/tube नथिचिएको जाँच्ने। Procedure, समय, बिरामीको अवस्था र position का जोखिम विचार गर्ने। Table tilt वा ठूलो movement पछि पुनः जाँच्ने र policy अनुसार उपकरण तथा छालाको जाँच लेख्ने।"],["Post-Anaesthesia Care & Handover","Transfer to recovery only when the anaesthesia team considers it safe and monitoring/oxygen support are maintained. Give a structured handover covering procedure, anaesthesia, airway, allergies, medicines, fluids, blood loss, drains, complications, analgesia, antiemetics and specific concerns. In recovery, assess airway, breathing, circulation, consciousness, pain, nausea, temperature, wound and drain status. Discharge requires documented criteria and authorized clinical review; escalate deterioration immediately.","Anaesthesia team ले सुरक्षित ठानेपछि मात्र monitoring र आवश्यक oxygen support सहित recovery मा सार्ने। Procedure, anaesthesia, airway, allergy, औषधि, fluid, blood loss, drain, complication, pain medicine, antiemetic र विशेष चिन्ता समेटेर व्यवस्थित handover दिने। Recovery मा airway, breathing, circulation, चेतना, दुखाइ, वाकवाकी, तापक्रम, घाउ र drain जाँच्ने। Discharge का लागि documented criteria र अधिकृत clinical review चाहिन्छ; अवस्था बिग्रिए तुरुन्त जानकारी दिने।"],["OT Zones, Gas Supply & Scavenging","Operating departments commonly use unrestricted, semi-restricted and restricted zones to control traffic and contamination. Medical gas systems may include oxygen, medical air, nitrous oxide and vacuum, with zone valves and alarms. Scavenging removes waste anaesthetic gases. Staff should know emergency shut-off locations and report leaks or pressure alarms. Fire risk rises when oxidizers, ignition sources and fuel are present.","OT मा unrestricted, semi-restricted र restricted zone हुन्छन्। Medical gas system मा oxygen, medical air, nitrous oxide र vacuum हुन सक्छ; zone valve र alarm पनि हुन्छ। Scavenging ले waste anaesthetic gas हटाउँछ। Emergency shut-off कहाँ छ थाहा राख्ने र leak वा pressure alarm report गर्ने।"],["Anaesthesia Types & Special Patient Groups","Anaesthesia may be general, regional (spinal or epidural), local or monitored sedation, depending on procedure and patient factors. Children and older adults have different physiological and drug-response considerations. Historical stages of anaesthesia are useful for theory, but modern balanced anaesthesia relies on multiple agents and continuous monitoring. Hypothermia and induced hypotension are specialist techniques requiring defined indications and trained teams.","Anaesthesia general, regional (spinal वा epidural), local वा monitored sedation हुन सक्छ। बालबालिका र वृद्धमा physiology तथा औषधिको असर फरक हुन्छ। ऐतिहासिक anaesthesia stages theory का लागि उपयोगी छन्; आधुनिक balanced anaesthesia मा धेरै औषधि र निरन्तर monitoring हुन्छ। Hypothermia र induced hypotension विशेषज्ञले मात्र गर्छन्।"],["OT Team Roles, Counts & Cleaning","The scrub person maintains the sterile field and passes instruments; the circulating nurse coordinates non-sterile activities, documentation and supplies. Sponge, sharp and instrument counts are performed at defined points and discrepancies are escalated immediately. Used instruments are transported safely, cleaned before inspection and packaging, then sterilized. Environmental cleaning follows facility schedules for between-case, terminal, daily and periodic cleaning.","Scrub person sterile field कायम राखेर instrument पास गर्छ; circulating nurse non-sterile काम, documentation र supply समन्वय गर्छ। Sponge, sharp र instrument count तोकिएका समयमा गरिन्छ; नमिले तुरुन्त जानकारी दिनुपर्छ। Instrument सुरक्षित रूपमा लैजाने, सफा गर्ने, inspection/packaging पछि sterilize गर्ने। OT सफाइ hospital schedule अनुसार गर्नुपर्छ।"],["Specialty Surgery: Eye, ENT, Plastic, Cardiac & Neurosurgery","Ophthalmic procedures require delicate instruments and microscope-based precision. ENT surgery may involve ear, nose, oral cavity, throat, larynx and airway; protect the shared airway with anaesthesia. Plastic surgery includes grafts, flaps, burns and reconstruction. Cardiac surgery may involve open-heart procedures and catheter-based diagnostics. Neurosurgery includes burr holes, cranial and spinal procedures; careful positioning and neurological monitoring are important.","आँखाको surgery मा नाजुक instrument र microscope चाहिन्छ। ENT मा कान, नाक, मुख, घाँटी, larynx र airway पर्छन्; anaesthesia सँग airway सुरक्षित राख्नुपर्छ। Plastic surgery मा graft, flap, burn र reconstruction पर्छ। Cardiac surgery मा open-heart र catheter-based diagnosis हुन सक्छ। Neurosurgery मा burr hole, cranial र spinal procedure पर्छन्।"],["Surgical Complications & Recognition","Potential complications include pulmonary and cardiovascular events, haemorrhage, shock, DIC, wound infection, dehiscence, renal injury and electrolyte imbalance. Recognize trends such as tachycardia, hypotension, altered consciousness, reduced urine output, increasing drain output, fever or respiratory distress. Escalate promptly, support airway/breathing/circulation within role and document actions. Management is cause-specific and follows emergency protocols.","सम्भावित complication मा pulmonary र cardiovascular समस्या, haemorrhage, shock, DIC, wound infection, dehiscence, renal injury र electrolyte imbalance पर्छन्। Tachycardia, hypotension, चेतना बदलिनु, urine कम हुनु, drain मा रगत बढ्नु, ज्वरो वा सास फेर्न गाह्रो हुनु चिन्नुपर्छ। तुरुन्त जानकारी दिने र आफ्नो भूमिकाभित्र ABC सहयोग गर्ने।"]];
const state={mode:"",items:[],index:0,answers:{}};
const h=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const panel=html=>root.innerHTML=html;
const bank=Q.map((q,i)=>{const shift=(i*7+3)%4;const options=q[2].map((_,j)=>q[2][(j+shift)%4]);return [...q.slice(0,2),options,(q[3]-shift+4)%4,...q.slice(4)];});
function menu(){panel('<div class="notice"><b>NHPC Diploma in Operation Theatre Technology</b><p>आधिकारिक २०२१ syllabus अनुसार अध्ययन नक्सा। हाल २७१ वटा bilingual MCQ छन् (१४४ Practice + १२७ Mock)।</p></div><div class="topic-grid">'+topics.map(t=>'<article class="topic-card"><b>'+h(t[0])+'</b><small>'+h(t[1])+'</small><p>'+h(t[2])+'</p></article>').join('')+'</div><h3>विस्तृत Notes • Part 1 र Part 2</h3><p class="muted">English र नेपालीमा सरल व्याख्या। शीर्षक खोल्न थिच्नुहोस्।</p><div class="topic-grid">'+detailedNotes.map(n=>'<details class="topic-card"><summary><b>'+h(n[0])+'</b></summary><p><b>English:</b> '+h(n[1])+'</p><p class="np"><b>नेपाली:</b> '+h(n[2])+'</p></details>').join('')+'</div><h3>MCQ अभ्यास</h3><div class="ha-actions"><button data-ott="practice">MCQ Practice (144)</button><button data-ott="mock">Mini Mock Test (127)</button></div><h3>अध्ययन कसरी गर्ने?</h3><ol><li>पहिले Notes पढ्नुहोस्।</li><li>MCQ Practice मा उत्तर छानेर व्याख्या हेर्नुहोस्।</li><li>Mock Test मा सबै प्रश्न हल गरेपछि नतिजा हेर्नुहोस्।</li></ol><p class="disclaimer">यो स्वतन्त्र शैक्षिक अभ्यास सामग्री हो, आधिकारिक प्रश्नपत्र होइन। Clinical काममा आफ्नो scope र संस्थागत SOP पालना गर्नुहोस्।</p>');}
function begin(mode){state.mode=mode;state.items=bank.slice(mode==="practice"?0:144,mode==="practice"?144:bank.length);state.index=0;state.answers={};render();}
function render(){const q=state.items[state.index],sel=state.answers[state.index],done=sel!==undefined;panel('<p class="muted">'+(state.mode==="practice"?"MCQ Practice":"Mini Mock Test")+' • प्रश्न '+(state.index+1)+' / '+state.items.length+' • '+h(q[6])+'</p><article class="ha-question"><h3>'+h(q[0])+'</h3><p class="np">'+h(q[1])+'</p><div class="ha-options">'+q[2].map((o,i)=>'<button class="'+(sel===i?"selected":"")+'" data-ott-option="'+i+'">'+String.fromCharCode(65+i)+'. '+h(o)+'</button>').join("")+'</div>'+(done?'<div class="ha-explain"><b>'+(sel===q[3]?"सही उत्तर!":"सही उत्तर: "+h(q[2][q[3]]))+'</b><p>'+h(q[4])+'</p><p class="np">'+h(q[5])+'</p></div>':"")+'</article><div class="ha-nav"><button data-ott-prev '+(state.index===0?"disabled":"")+'>← अघिल्लो</button><button data-ott-next>'+(state.index===state.items.length-1?"नतिजा हेर्नुहोस्":"अर्को →")+'</button></div><button data-ott="menu" class="smallbtn">मुख्य मेनु</button>');}
function finish(){let score=0;const rows=state.items.map((q,i)=>{const ok=state.answers[i]===q[3];if(ok)score++;return '<article class="ha-review"><b>'+(i+1)+'. '+h(q[0])+'</b><p class="'+(ok?"correct":"incorrect")+'">'+(ok?"सही उत्तर":"गलत/छुटेको उत्तर")+' • '+h(q[2][q[3]])+'</p><p>'+h(q[4])+'</p><p class="np">'+h(q[5])+'</p></article>';});if(window.DHPNProgress)window.DHPNProgress.recordMock("NHPC Diploma in Operation Theatre Technology",score,state.items.length);panel('<div class="ha-result"><h3>अभ्यास नतिजा</h3><div class="ha-score">'+score+' / '+state.items.length+'</div><b>'+Math.round(score/state.items.length*100)+'% सही</b><p>यो अभ्यास नतिजा हो, NHPC को आधिकारिक pass mark होइन।</p></div><h3>उत्तर समीक्षा</h3>'+rows.join("")+'<button data-ott="menu" class="smallbtn">मुख्य मेनुमा फर्कनुहोस्</button>');}
root.addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;if(b.dataset.ott){if(b.dataset.ott==="menu")menu();else begin(b.dataset.ott);return;}if(b.dataset.ottOption!==undefined){state.answers[state.index]=Number(b.dataset.ottOption);render();if(state.mode==="practice"&&window.DHPNProgress){const q=state.items[state.index];window.DHPNProgress.recordMCQ("NHPC Diploma in Operation Theatre Technology",[q[0],q[1],q[2],q[3],q[4],q[5]],state.answers[state.index]);}return;}if(b.dataset.ottPrev!==undefined){state.index=Math.max(0,state.index-1);render();return;}if(b.dataset.ottNext!==undefined){if(state.index===state.items.length-1){if(state.items.some((_,i)=>state.answers[i]===undefined)){alert("सबै प्रश्नको उत्तर दिएपछि मात्र नतिजा हेर्नुहोस्।");return;}finish();}else{state.index++;render();}}});menu();})();